"""Embedded Lua Assets"""

SOMALIA_TEST_LUA = '--[[\n    SOMALIA - ETAPA 1: SCRIPT DE DIAGNÓSTICO MÍNIMO\n    Isolado de qualquer dependência externa (Sem ImGui, Sem KeyAuth, Sem Módulos)\n    Objetivo: Provar se o MoonLoader está executando scripts Lua no GTA/SA-MP\n]]\n\nprint("[SOMALIA-TEST] ========================================")\nprint("[SOMALIA-TEST] 1. Lua script carregado no MoonLoader!")\nprint("[SOMALIA-TEST] ========================================")\n\nfunction main()\n    print("[SOMALIA-TEST] 2. Entrou na thread main(). Aguardando SA-MP...")\n\n    -- Aguarda o SA-MP estar disponível\n    while not isSampAvailable() do\n        wait(100)\n    end\n\n    print("[SOMALIA-TEST] 3. SA-MP disponivel e detectado com sucesso!")\n    \n    -- Envia mensagem nítida em verde no chat do SA-MP\n    sampAddChatMessage("{00FF00}[SOMALIA-TEST]{FFFFFF} Runtime MoonLoader funcionando com sucesso!", -1)\n    sampAddChatMessage("{00FF00}[SOMALIA-TEST]{FFFFFF} O ambiente Lua basico esta 100% operacional.", -1)\n\n    print("[SOMALIA-TEST] 4. Mensagem enviada ao chat. Loop basico iniciado.")\n\n    while true do\n        wait(1000)\n    end\nend\n'

SOMALIA_IMGUI_TEST_LUA = '--[[\n    SOMALIA - ETAPA 5: TESTE MÍNIMO DE IMGUI & HOTKEY F5\n    Isolado de módulos complexos. Testa apenas se a lib ImGui renderiza janelas e se o F5 responde.\n]]\n\nlocal okImgui, imgui = pcall(require, \'imgui\')\nlocal showTestWindow = okImgui and imgui.ImBool(false) or { v = false }\n\nfunction main()\n    print("[SOMALIA-IMGUI-TEST] ========================================")\n    print("[SOMALIA-IMGUI-TEST] 1. Script de teste ImGui carregado!")\n    print("[SOMALIA-IMGUI-TEST] 2. Status lib ImGui encontrada: " .. tostring(okImgui))\n\n    while not isSampAvailable() do\n        wait(100)\n    end\n\n    if okImgui then\n        sampAddChatMessage("{0080FF}[SOMALIA-IMGUI-TEST]{FFFFFF} ImGui detectado! Pressione {0080FF}F5{FFFFFF} para testar janela.", -1)\n    else\n        sampAddChatMessage("{FF0000}[SOMALIA-IMGUI-TEST]{FFFFFF} ERRO: Biblioteca ImGui ausente em moonloader/lib!", -1)\n    end\n\n    while true do\n        wait(0)\n\n        if isKeyJustPressed(0x74) then -- 0x74 = VK_F5\n            if okImgui then\n                showTestWindow.v = not showTestWindow.v\n                print("[SOMALIA-IMGUI-TEST] F5 Pressionado! Janela aberta: " .. tostring(showTestWindow.v))\n            end\n        end\n\n        if okImgui then\n            imgui.Process = showTestWindow.v\n            imgui.ShowCursor = showTestWindow.v\n        end\n    end\nend\n\nif okImgui then\n    function imgui.OnDrawFrame()\n        if showTestWindow.v then\n            local sw, sh = getScreenResolution()\n            imgui.SetNextWindowPos(imgui.ImVec2(sw / 2, sh / 2), imgui.Cond.FirstUseEver, imgui.ImVec2(0.5, 0.5))\n            imgui.SetNextWindowSize(imgui.ImVec2(350, 200), imgui.Cond.FirstUseEver)\n            imgui.Begin("SOMALIA - TESTE DE IMGUI", showTestWindow)\n            imgui.Text("Se voce esta vendo este texto, o ImGui e o F5 estao funcionando!")\n            imgui.Spacing()\n            if imgui.Button("Fechar Janela", imgui.ImVec2(-1, 30)) then\n                showTestWindow.v = false\n            end\n            imgui.End()\n        end\n    end\nend\n\nfunction isKeyJustPressed(key)\n    if isKeyDown(key) then\n        if not keyWasDown then\n            keyWasDown = true\n            return true\n        end\n    else\n        keyWasDown = false\n    end\n    return false\nend\n'

EMBEDDED_MODULES = {'somalia/theme.lua': '--[[\n    Somalia - Theme & Styling Module\n    Preserva a identidade visual SML Neon Blue (#0A0B10, #0F1117, #0080FF)\n]]\n\nlocal okImgui, imgui = pcall(require, \'imgui\')\n\nlocal Theme = {\n    Colors = {\n        Background      = okImgui and imgui.ImVec4(0.04, 0.04, 0.06, 1.00) or {0.04, 0.04, 0.06, 1.00}, -- #0A0B10\n        SidebarBg       = okImgui and imgui.ImVec4(0.04, 0.04, 0.06, 1.00) or {0.04, 0.04, 0.06, 1.00},\n        CardBg          = okImgui and imgui.ImVec4(0.06, 0.07, 0.09, 1.00) or {0.06, 0.07, 0.09, 1.00}, -- #0F1117\n        CardBorder      = okImgui and imgui.ImVec4(0.12, 0.14, 0.18, 0.85) or {0.12, 0.14, 0.18, 0.85}, -- #1E232E\n        AccentPrimary   = okImgui and imgui.ImVec4(0.00, 0.50, 1.00, 1.00) or {0.00, 0.50, 1.00, 1.00}, -- #0080FF\n        AccentHover     = okImgui and imgui.ImVec4(0.12, 0.60, 1.00, 1.00) or {0.12, 0.60, 1.00, 1.00}, -- #1E96FF\n        AccentActive    = okImgui and imgui.ImVec4(0.00, 0.40, 0.85, 1.00) or {0.00, 0.40, 0.85, 1.00}, -- #0066D9\n        AccentDark      = okImgui and imgui.ImVec4(0.10, 0.15, 0.25, 1.00) or {0.10, 0.15, 0.25, 1.00}, -- #182640\n        TextPrimary     = okImgui and imgui.ImVec4(0.96, 0.97, 1.00, 1.00) or {0.96, 0.97, 1.00, 1.00}, -- #F5F7FF\n        TextSecondary   = okImgui and imgui.ImVec4(0.50, 0.54, 0.62, 1.00) or {0.50, 0.54, 0.62, 1.00}, -- #808A9E\n        TextMuted       = okImgui and imgui.ImVec4(0.35, 0.38, 0.45, 1.00) or {0.35, 0.38, 0.45, 1.00},\n        Success         = okImgui and imgui.ImVec4(0.10, 0.80, 0.45, 1.00) or {0.10, 0.80, 0.45, 1.00},\n        Danger          = okImgui and imgui.ImVec4(0.95, 0.25, 0.25, 1.00) or {0.95, 0.25, 0.25, 1.00},\n        Warning         = okImgui and imgui.ImVec4(0.98, 0.70, 0.15, 1.00) or {0.98, 0.70, 0.15, 1.00}\n    },\n    Sizes = {\n        Window          = okImgui and imgui.ImVec2(780, 540) or {780, 540},\n        SidebarWidth    = 150,\n        CardHeight      = 460\n    },\n    Rounding = {\n        Window          = 10.0,\n        Card            = 8.0,\n        Button          = 6.0,\n        Slider          = 8.0,\n        Checkbox        = 4.0\n    },\n    Fonts = {\n        Main            = nil,\n        Bold            = nil,\n        Title           = nil,\n        Logo            = nil,\n        Small           = nil\n    }\n}\n\nfunction Theme.initFonts()\n    if not okImgui then return end\n    pcall(function()\n        local imguiIO = imgui.GetIO()\n        local winDir = os.getenv("WINDIR") or "C:\\\\Windows"\n        local segoeB = winDir .. "\\\\Fonts\\\\segoeuib.ttf"\n        local segoe  = winDir .. "\\\\Fonts\\\\segoeui.ttf"\n        local arialB = winDir .. "\\\\Fonts\\\\arialbd.ttf"\n        local arial  = winDir .. "\\\\Fonts\\\\arial.ttf"\n        \n        local fontPath = nil\n        local f = _G.io.open(segoeB, "r")\n        if f then f:close(); fontPath = segoeB end\n        \n        if not fontPath then\n            f = _G.io.open(arialB, "r")\n            if f then f:close(); fontPath = arialB end\n        end\n        if not fontPath then\n            f = _G.io.open(segoe, "r")\n            if f then f:close(); fontPath = segoe end\n        end\n        if not fontPath then\n            f = _G.io.open(arial, "r")\n            if f then f:close(); fontPath = arial end\n        end\n        \n        if fontPath then\n            Theme.Fonts.Main  = imguiIO.Fonts:AddFontFromFileTTF(fontPath, 16.0)\n            Theme.Fonts.Bold  = imguiIO.Fonts:AddFontFromFileTTF(fontPath, 17.5)\n            Theme.Fonts.Title = imguiIO.Fonts:AddFontFromFileTTF(fontPath, 20.0)\n            Theme.Fonts.Logo  = imguiIO.Fonts:AddFontFromFileTTF(fontPath, 26.0)\n            Theme.Fonts.Small = imguiIO.Fonts:AddFontFromFileTTF(fontPath, 13.5)\n        end\n    end)\nend\n\nfunction Theme.applyStyle()\n    if not okImgui then return end\n    pcall(function()\n        local style = imgui.GetStyle()\n        local colors = style.Colors\n        local clr = imgui.Col\n\n        style.WindowRounding = Theme.Rounding.Window\n        style.FrameRounding = Theme.Rounding.Button\n        style.GrabRounding = Theme.Rounding.Slider\n        style.ScrollbarRounding = 4.0\n        style.WindowPadding = imgui.ImVec2(14, 14)\n        style.ItemSpacing = imgui.ImVec2(8, 8)\n        style.ItemInnerSpacing = imgui.ImVec2(6, 6)\n\n        pcall(function() style.ChildWindowRounding = Theme.Rounding.Card end)\n        pcall(function() style.ChildRounding = Theme.Rounding.Card end)\n\n        if clr.WindowBg then colors[clr.WindowBg] = Theme.Colors.Background end\n        if clr.ChildWindowBg then colors[clr.ChildWindowBg] = Theme.Colors.CardBg end\n        if clr.ChildBg then colors[clr.ChildBg] = Theme.Colors.CardBg end\n        if clr.Border then colors[clr.Border] = Theme.Colors.CardBorder end\n        if clr.BorderShadow then colors[clr.BorderShadow] = imgui.ImVec4(0, 0, 0, 0) end\n        \n        if clr.TitleBg then colors[clr.TitleBg] = Theme.Colors.Background end\n        if clr.TitleBgActive then colors[clr.TitleBgActive] = Theme.Colors.Background end\n        if clr.Button then colors[clr.Button] = Theme.Colors.AccentPrimary end\n        if clr.ButtonHovered then colors[clr.ButtonHovered] = Theme.Colors.AccentHover end\n        if clr.ButtonActive then colors[clr.ButtonActive] = Theme.Colors.AccentActive end\n        \n        if clr.Text then colors[clr.Text] = Theme.Colors.TextPrimary end\n        if clr.TextDisabled then colors[clr.TextDisabled] = Theme.Colors.TextMuted end\n    end)\nend\n\nreturn Theme\n', 'somalia/notifications.lua': '--[[\n    Somalia - Notifications System\n    Toasts modernos animados no canto inferior/superior com fade, cores de status e anti-spam\n]]\n\nlocal okImgui, imgui = pcall(require, \'imgui\')\nlocal Theme = nil\n\nlocal Notifications = {\n    queue = {},\n    maxDisplay = 5,\n    defaultDuration = 3.5,\n    lastMessages = {}\n}\n\nfunction Notifications.init(themeModule)\n    Theme = themeModule\nend\n\nfunction Notifications.add(title, message, nType, duration)\n    local now = os.clock()\n    local key = (title or "") .. ":" .. (message or "")\n    \n    if Notifications.lastMessages[key] and (now - Notifications.lastMessages[key]) < 1.0 then\n        return\n    end\n    Notifications.lastMessages[key] = now\n    \n    duration = duration or Notifications.defaultDuration\n    \n    table.insert(Notifications.queue, {\n        title = title or "SOMALIA",\n        message = message or "",\n        nType = nType or "info",\n        startTime = now,\n        duration = duration,\n        alpha = 0.0,\n        slideX = 30.0\n    })\n    \n    if #Notifications.queue > Notifications.maxDisplay then\n        table.remove(Notifications.queue, 1)\n    end\nend\n\nfunction Notifications.success(title, msg, dur)\n    Notifications.add(title, msg, "success", dur)\nend\n\nfunction Notifications.error(title, msg, dur)\n    Notifications.add(title, msg, "error", dur)\nend\n\nfunction Notifications.warning(title, msg, dur)\n    Notifications.add(title, msg, "warning", dur)\nend\n\nfunction Notifications.info(title, msg, dur)\n    Notifications.add(title, msg, "info", dur)\nend\n\nfunction Notifications.render(customDrawList)\n    if not okImgui or #Notifications.queue == 0 then return end\n    \n    local now = os.clock()\n    local sw, sh = getScreenResolution()\n    local drawList = customDrawList or (imgui.GetWindowDrawList and imgui.GetWindowDrawList())\n    if not drawList then return end\n    \n    local toastW = 240\n    local toastH = 48\n    local margin = 16\n    local startY = sh - margin - toastH\n    local startX = sw - margin - toastW\n    \n    local i = #Notifications.queue\n    while i >= 1 do\n        local toast = Notifications.queue[i]\n        local elapsed = now - toast.startTime\n        local remaining = toast.duration - elapsed\n        \n        if remaining <= 0 then\n            table.remove(Notifications.queue, i)\n        else\n            local fadeInTime = 0.25\n            local fadeOutTime = 0.35\n            \n            if elapsed < fadeInTime then\n                local prog = elapsed / fadeInTime\n                toast.alpha = prog\n                toast.slideX = (1.0 - prog) * 40.0\n            elseif remaining < fadeOutTime then\n                local prog = remaining / fadeOutTime\n                toast.alpha = prog\n                toast.slideX = (1.0 - prog) * 40.0\n            else\n                toast.alpha = 1.0\n                toast.slideX = 0.0\n            end\n            \n            local curX = startX + toast.slideX\n            local curY = startY - ((#Notifications.queue - i) * (toastH + 8))\n            \n            local a = math.floor(toast.alpha * 255)\n            local bgCol = imgui.ImColor(10, 12, 17, math.floor(a * 0.94)):GetU32()\n            local borderCol = imgui.ImColor(28, 34, 46, a):GetU32()\n            \n            local accentCol = imgui.ImColor(0, 128, 255, a):GetU32()\n            local iconChar = "i"\n            if toast.nType == "success" then\n                accentCol = imgui.ImColor(30, 215, 96, a):GetU32()\n                iconChar = "OK"\n            elseif toast.nType == "error" then\n                accentCol = imgui.ImColor(255, 60, 60, a):GetU32()\n                iconChar = "X"\n            elseif toast.nType == "warning" then\n                accentCol = imgui.ImColor(255, 174, 25, a):GetU32()\n                iconChar = "!"\n            end\n            \n            drawList:AddRectFilled(imgui.ImVec2(curX, curY), imgui.ImVec2(curX + toastW, curY + toastH), bgCol, 6.0)\n            drawList:AddRect(imgui.ImVec2(curX, curY), imgui.ImVec2(curX + toastW, curY + toastH), borderCol, 6.0, 15, 1.2)\n            drawList:AddRectFilled(imgui.ImVec2(curX, curY), imgui.ImVec2(curX + 4, curY + toastH), accentCol, 2.0)\n            \n            drawList:AddCircleFilled(imgui.ImVec2(curX + 22, curY + (toastH / 2)), 10.0, accentCol)\n            local iSize = imgui.CalcTextSize(iconChar)\n            drawList:AddText(imgui.ImVec2(curX + 22 - (iSize.x / 2), curY + (toastH / 2) - (iSize.y / 2)), imgui.ImColor(255, 255, 255, a):GetU32(), iconChar)\n            \n            drawList:AddText(imgui.ImVec2(curX + 40, curY + 8), imgui.ImColor(255, 255, 255, a):GetU32(), toast.title)\n            drawList:AddText(imgui.ImVec2(curX + 40, curY + 24), imgui.ImColor(170, 182, 205, a):GetU32(), toast.message)\n        end\n        i = i - 1\n    end\nend\n\nreturn Notifications\n', 'somalia/keybinds.lua': '--[[\n    Somalia - Universal Keybind System\n    Captura e gerenciamento de teclas do teclado e mouse sem loops bloqueantes\n    Proteção contra interferência em diálogos e chat do SA-MP\n]]\n\nlocal okVkeys, vkeys = pcall(require, \'vkeys\')\nlocal okImgui, imgui = pcall(require, \'imgui\')\n\nlocal Keybinds = {\n    listeningFor = nil,\n    keyStates = {},\n    keyNames = {\n        [0x01] = "Mouse 1",\n        [0x02] = "Mouse 2",\n        [0x04] = "Mouse 3",\n        [0x05] = "Mouse 4",\n        [0x06] = "Mouse 5",\n        [0x08] = "Backspace",\n        [0x09] = "Tab",\n        [0x0D] = "Enter",\n        [0x10] = "Shift",\n        [0x11] = "Ctrl",\n        [0x12] = "Alt",\n        [0x13] = "Pause",\n        [0x14] = "Caps Lock",\n        [0x1B] = "Escape",\n        [0x20] = "Space",\n        [0x21] = "Page Up",\n        [0x22] = "Page Down",\n        [0x23] = "End",\n        [0x24] = "Home",\n        [0x25] = "Left",\n        [0x26] = "Up",\n        [0x27] = "Right",\n        [0x28] = "Down",\n        [0x2D] = "Insert",\n        [0x2E] = "Delete",\n        [0x70] = "F1",\n        [0x71] = "F2",\n        [0x72] = "F3",\n        [0x73] = "F4",\n        [0x74] = "F5",\n        [0x75] = "F6",\n        [0x76] = "F7",\n        [0x77] = "F8",\n        [0x78] = "F9",\n        [0x79] = "F10",\n        [0x7A] = "F11",\n        [0x7B] = "F12"\n    }\n}\n\nfor i = 0x30, 0x39 do\n    Keybinds.keyNames[i] = string.char(i)\nend\nfor i = 0x41, 0x5A do\n    Keybinds.keyNames[i] = string.char(i)\nend\nfor i = 0x60, 0x69 do\n    Keybinds.keyNames[i] = "Num " .. (i - 0x60)\nend\n\nfunction Keybinds.getKeyName(keyCode)\n    if not keyCode or keyCode == 0 then return "None" end\n    return Keybinds.keyNames[keyCode] or ("Key 0x" .. string.format("%X", keyCode))\nend\n\nfunction Keybinds.isJustPressed(keyCode)\n    if not keyCode or keyCode == 0 then return false end\n    if isSampLoaded() and (sampIsDialogActive() or sampIsChatInputActive()) then return false end\n    local isDown = isKeyDown(keyCode)\n    local wasDown = Keybinds.keyStates[keyCode] or false\n    Keybinds.keyStates[keyCode] = isDown\n    return isDown and not wasDown\nend\n\nfunction Keybinds.isPressed(keyCode)\n    if not keyCode or keyCode == 0 then return false end\n    if isSampLoaded() and (sampIsDialogActive() or sampIsChatInputActive()) then return false end\n    return isKeyDown(keyCode)\nend\n\nfunction Keybinds.processListening(onKeyBound)\n    if not Keybinds.listeningFor then return end\n    if isSampLoaded() and (sampIsDialogActive() or sampIsChatInputActive()) then return end\n    \n    if isKeyDown(0x1B) then -- VK_ESCAPE\n        local id = Keybinds.listeningFor\n        Keybinds.listeningFor = nil\n        if onKeyBound then onKeyBound(id, 0) end\n        return\n    end\n    \n    for k = 1, 255 do\n        if k ~= 0x1B and isKeyDown(k) then\n            local id = Keybinds.listeningFor\n            Keybinds.listeningFor = nil\n            if onKeyBound then onKeyBound(id, k) end\n            return\n        end\n    end\nend\n\nfunction Keybinds.drawKeybindButton(idStr, currentKey, onKeyChange, width)\n    if not okImgui then return false end\n    \n    width = width or 75\n    local isListening = (Keybinds.listeningFor == idStr)\n    local label = isListening and "[ ... ]" or ("[ " .. Keybinds.getKeyName(currentKey) .. " ]")\n    \n    local pos = imgui.GetCursorScreenPos()\n    local drawList = imgui.GetWindowDrawList()\n    \n    imgui.PushID("kb_" .. idStr)\n    local clicked = imgui.InvisibleButton("##btn_" .. idStr, imgui.ImVec2(width, 20))\n    local hovered = imgui.IsItemHovered()\n    imgui.PopID()\n    \n    if clicked then\n        if Keybinds.listeningFor == idStr then\n            Keybinds.listeningFor = nil\n        else\n            Keybinds.listeningFor = idStr\n        end\n    end\n    \n    local bgCol = isListening and imgui.ImColor(0, 100, 200, 200):GetU32() or (hovered and imgui.ImColor(25, 32, 45, 255):GetU32() or imgui.ImColor(14, 18, 26, 255):GetU32())\n    local borderCol = isListening and imgui.ImColor(0, 180, 255, 255):GetU32() or (hovered and imgui.ImColor(0, 128, 255, 180):GetU32() or imgui.ImColor(35, 45, 60, 200):GetU32())\n    local txtCol = isListening and imgui.ImColor(255, 255, 255, 255):GetU32() or (hovered and imgui.ImColor(0, 160, 255, 255):GetU32() or imgui.ImColor(140, 158, 185, 255):GetU32())\n    \n    drawList:AddRectFilled(pos, imgui.ImVec2(pos.x + width, pos.y + 20), bgCol, 4.0)\n    drawList:AddRect(pos, imgui.ImVec2(pos.x + width, pos.y + 20), borderCol, 4.0)\n    \n    local txtSize = imgui.CalcTextSize(label)\n    drawList:AddText(imgui.ImVec2(pos.x + (width - txtSize.x) / 2, pos.y + (20 - txtSize.y) / 2), txtCol, label)\n    \n    return clicked\nend\n\nreturn Keybinds\n', 'somalia/config.lua': '--[[\n    Somalia - Multi-Profile Configuration System\n    Gerenciamento de múltiplos perfis 100% compatível com a estrutura de seções do inicfg\n]]\n\nlocal okInicfg, inicfg = pcall(require, \'inicfg\')\n\nlocal Config = {\n    currentProfile = "default",\n    profilesList = {"default", "legit", "movement", "rage", "visuals"},\n    data = {},\n    weaponsList = {\n        { id = 24, name = "Desert Eagle" },\n        { id = 31, name = "M4" },\n        { id = 30, name = "AK-47" },\n        { id = 25, name = "Shotgun" },\n        { id = 26, name = "Sawnoff" },\n        { id = 27, name = "Combat Shotgun" },\n        { id = 29, name = "MP5" },\n        { id = 32, name = "Tec-9" },\n        { id = 28, name = "Micro Uzi" },\n        { id = 34, name = "Sniper Rifle" },\n        { id = 33, name = "Country Rifle" },\n        { id = 22, name = "Pistol (Colt 45)" },\n        { id = 23, name = "Silenced 9mm" }\n    }\n}\n\n-- Configurações padrão individuais por arma\nlocal function getDefaultWeaponSettings(wId)\n    local isSniper = (wId == 34 or wId == 33)\n    local isShotgun = (wId == 25 or wId == 26 or wId == 27)\n    local isFast = (wId == 28 or wId == 29 or wId == 30 or wId == 31 or wId == 32)\n    \n    return {\n        aim = {\n            enabled = true,\n            showFov = true,\n            fovSize = isSniper and 35 or (isShotgun and 80 or (isFast and 50 or 65)),\n            smoothH = isSniper and 6 or (isFast and 15 or 12),\n            smoothV = isSniper and 8 or (isFast and 16 or 14),\n            maxDist = isSniper and 250 or (isShotgun and 50 or 150),\n            hitbox = (isSniper or wId == 24) and 0 or 2, -- 0 = Head, 2 = Chest\n            allowNpc = false,\n            visibleCheck = true\n        },\n        silent = {\n            enabled = false,\n            showFov = false,\n            fovSize = isSniper and 45 or 70,\n            hitbox = 0,\n            allowNpc = false,\n            visibleCheck = true\n        }\n    }\nend\n\n-- Estrutura de dados padrão de um perfil (com seções planas para o inicfg)\nlocal function getDefaultSettings()\n    local settings = {\n        -- Sistema & Interface\n        system = {\n            menuKey = 0x74,           -- F5\n            accentR = 0.0,\n            accentG = 0.50,\n            accentB = 1.0,\n            autoLoadProfile = "default"\n        },\n        -- Aba 1: Aim Master Switches\n        aim = {\n            globalEnabled = true,     -- Master Switch do Aimbot\n            key = 0x02,               -- Mouse 2 (Botão Direito)\n            selectedWeaponIndex = 0   -- Índice no dropdown de armas\n        },\n        silent = {\n            globalEnabled = false,    -- Master Switch do Silent Aim\n            key = 0x02,               -- Mouse 2\n            selectedWeaponIndex = 0\n        },\n        -- Aba 2: Visuals (ESP)\n        visuals = {\n            enabled = false,\n            boxEsp = true,\n            cornerBox = false,\n            skeleton = false,\n            healthBar = true,\n            armorBar = true,\n            playerNames = true,\n            playerId = true,\n            distance = true,\n            weaponName = false,\n            snaplines = false,\n            fovCircle = true,\n            crosshair = false,\n            maxDistance = 250,\n            colorVisR = 0, colorVisG = 200, colorVisB = 255,\n            colorInvisR = 255, colorInvisG = 80, colorInvisB = 80\n        },\n        -- Aba 3: World\n        world = {\n            customTimeEnabled = false,\n            customHour = 12,\n            customMinute = 0,\n            customWeatherEnabled = false,\n            weatherId = 1             -- 1 = Sunny/Clear\n        },\n        -- Aba 4: Vehicles\n        vehicles = {\n            speedBoost = false,\n            speedBoostKey = 0x10,     -- Shift\n            speedMultiplier = 1.35,\n            instantRepair = false,\n            instantRepairKey = 0x52,  -- R\n            flipCar = false,\n            flipCarKey = 0x58,        -- X\n            godmode = false,\n            engineAlwaysOn = false,\n            vehicleEsp = false\n        },\n        -- Aba 5: Player & Movement (C-Slide original preservado)\n        player = {\n            scriptAtivo = true,\n            cSlideAtivo = true,\n            duracaoC = 10,            -- Duração do toque no C em ms\n            autoSlideAtivo = false,   -- Quick Switch (Soco e volta)\n            delayTroca = 0,\n            margem_snp = 550,\n            margem_desert = 0,\n            margem_m4 = 0,\n            margem_ak = 0,\n            margem_shot = 0,\n            infiniteStamina = false,\n            noFallDamage = false,\n            sprintSpeed = 1.0\n        },\n        -- Aba 6: Misc & Exploits\n        misc = {\n            noRecoil = false,\n            noSpread = false,\n            fastReload = false\n        },\n        -- HUD / Watermark\n        hud = {\n            watermark = true,\n            fps = true,\n            ping = true,\n            coords = false,\n            serverInfo = true,\n            activeFeatures = true\n        }\n    }\n\n    -- Seções planas de armas suportadas pelo inicfg\n    for _, w in ipairs(Config.weaponsList) do\n        local def = getDefaultWeaponSettings(w.id)\n        settings["aim_w_" .. w.id] = def.aim\n        settings["silent_w_" .. w.id] = def.silent\n    end\n\n    return settings\nend\n\n-- Deep copy de tabelas\nlocal function copyTable(orig)\n    local orig_type = type(orig)\n    local copy\n    if orig_type == \'table\' then\n        copy = {}\n        for orig_key, orig_value in next, orig, nil do\n            copy[copyTable(orig_key)] = copyTable(orig_value)\n        end\n    else\n        copy = orig\n    end\n    return copy\nend\n\n-- Mescla recursivamente garantindo tipos válidos\nlocal function mergeTables(target, source)\n    for k, v in pairs(source) do\n        if type(v) == \'table\' then\n            if type(target[k]) == \'table\' then\n                mergeTables(target[k], v)\n            else\n                target[k] = copyTable(v)\n            end\n        else\n            if target[k] == nil or type(target[k]) ~= type(v) then\n                target[k] = v\n            end\n        end\n    end\nend\n\nfunction Config.init()\n    Config.data = getDefaultSettings()\n    Config.load(Config.currentProfile)\nend\n\nfunction Config.getFilePath(profileName)\n    profileName = profileName or Config.currentProfile\n    return "somalia_" .. string.lower(profileName) .. ".ini"\nend\n\nfunction Config.save(profileName)\n    profileName = profileName or Config.currentProfile\n    local file = Config.getFilePath(profileName)\n    if okInicfg and Config.data then\n        pcall(function()\n            inicfg.save(Config.data, file)\n        end)\n    end\nend\n\nfunction Config.load(profileName)\n    profileName = profileName or Config.currentProfile\n    local file = Config.getFilePath(profileName)\n    local defaults = getDefaultSettings()\n    \n    if okInicfg then\n        local loaded = inicfg.load(defaults, file)\n        if loaded and type(loaded) == \'table\' then\n            mergeTables(loaded, defaults)\n            Config.data = loaded\n            Config.currentProfile = profileName\n            return true\n        end\n    end\n    Config.data = defaults\n    Config.currentProfile = profileName\n    Config.save(profileName)\n    return false\nend\n\nfunction Config.reset()\n    Config.data = getDefaultSettings()\n    Config.save(Config.currentProfile)\nend\n\nfunction Config.getAimWeapon(wId)\n    local key = "aim_w_" .. tostring(wId)\n    if type(Config.data[key]) ~= \'table\' then\n        local def = getDefaultWeaponSettings(wId)\n        Config.data[key] = def.aim\n    end\n    return Config.data[key]\nend\n\nfunction Config.getSilentWeapon(wId)\n    local key = "silent_w_" .. tostring(wId)\n    if type(Config.data[key]) ~= \'table\' then\n        local def = getDefaultWeaponSettings(wId)\n        Config.data[key] = def.silent\n    end\n    return Config.data[key]\nend\n\nreturn Config\n', 'somalia/hud.lua': '--[[\n    Somalia - HUD & Watermark Module\n    Renderização de overlay moderno e configurável (FPS, Ping, ID, Server, Coords e Active Features)\n    Protegido contra chamadas antes do spawn local\n]]\n\nlocal okImgui, imgui = pcall(require, \'imgui\')\n\nlocal HUD = {\n    fps = 0,\n    fpsCounter = 0,\n    lastFpsTime = 0\n}\n\nfunction HUD.render(config, customDrawList)\n    if not okImgui or not config or not config.hud then return end\n    \n    local now = os.clock()\n    HUD.fpsCounter = HUD.fpsCounter + 1\n    if (now - HUD.lastFpsTime) >= 1.0 then\n        HUD.fps = HUD.fpsCounter\n        HUD.fpsCounter = 0\n        HUD.lastFpsTime = now\n    end\n    \n    local drawList = customDrawList or (imgui.GetWindowDrawList and imgui.GetWindowDrawList())\n    if not drawList then return end\n    \n    local sw, sh = getScreenResolution()\n    \n    ---------------------------------------------------------\n    -- 1. WATERMARK SUPERIOR (SOMALIA | FPS | PING | TIME)\n    ---------------------------------------------------------\n    if config.hud.watermark then\n        local ping = 0\n        local nick = "Player"\n        local myId = -1\n        if isSampLoaded() and isSampAvailable() and sampIsLocalPlayerSpawned() and doesCharExist(playerPed) then\n            local res, id = sampGetPlayerIdByCharHandle(playerPed)\n            if res then\n                myId = id\n                nick = sampGetPlayerNickname(id) or "Player"\n                ping = sampGetPlayerPing(id) or 0\n            end\n        end\n        \n        local timeStr = os.date("%H:%M:%S")\n        local text = string.format("SOMALIA  |  %s [%d]  |  %d FPS  |  %dms  |  %s", nick, myId, HUD.fps, ping, timeStr)\n        local textSize = imgui.CalcTextSize(text)\n        \n        local padX, padY = 10, 5\n        local boxW = textSize.x + (padX * 2)\n        local boxH = textSize.y + (padY * 2)\n        local startX = sw - boxW - 14\n        local startY = 14\n        \n        -- Fundo escuro com borda e linha neon no topo\n        local bgCol = imgui.ImColor(10, 11, 16, 220):GetU32()\n        local borderCol = imgui.ImColor(30, 36, 48, 200):GetU32()\n        local neonCol = imgui.ImColor(0, 128, 255, 255):GetU32()\n        \n        drawList:AddRectFilled(imgui.ImVec2(startX, startY), imgui.ImVec2(startX + boxW, startY + boxH), bgCol, 5.0)\n        drawList:AddRect(imgui.ImVec2(startX, startY), imgui.ImVec2(startX + boxW, startY + boxH), borderCol, 5.0)\n        drawList:AddRectFilled(imgui.ImVec2(startX + 2, startY), imgui.ImVec2(startX + boxW - 2, startY + 2), neonCol, 2.0)\n        \n        drawList:AddText(imgui.ImVec2(startX + padX, startY + padY), imgui.ImColor(240, 245, 255, 255):GetU32(), text)\n    end\n    \n    ---------------------------------------------------------\n    -- 2. COORDENADAS (CANTO INFERIOR ESQUERDO)\n    ---------------------------------------------------------\n    if config.hud.coords and doesCharExist(playerPed) and not isCharDead(playerPed) then\n        local px, py, pz = getCharCoordinates(playerPed)\n        local coordText = string.format("X: %.2f  Y: %.2f  Z: %.2f", px, py, pz)\n        local cSize = imgui.CalcTextSize(coordText)\n        \n        local cX = 14\n        local cY = sh - 28\n        drawList:AddRectFilled(imgui.ImVec2(cX - 4, cY - 2), imgui.ImVec2(cX + cSize.x + 4, cY + cSize.y + 2), imgui.ImColor(10, 11, 16, 180):GetU32(), 4.0)\n        drawList:AddText(imgui.ImVec2(cX, cY), imgui.ImColor(0, 160, 255, 255):GetU32(), coordText)\n    end\n    \n    ---------------------------------------------------------\n    -- 3. ACTIVE FEATURES (LISTA DE FUNÇÕES ATIVAS NA TELA)\n    ---------------------------------------------------------\n    if config.hud.activeFeatures then\n        local activeList = {}\n        if config.aim and config.aim.globalEnabled then table.insert(activeList, "Aimbot") end\n        if config.silent and config.silent.globalEnabled then table.insert(activeList, "Silent Aim") end\n        if config.visuals and config.visuals.enabled then table.insert(activeList, "Visuals (ESP)") end\n        if config.player and config.player.cSlideAtivo then table.insert(activeList, "C-Slide") end\n        if config.player and config.player.autoSlideAtivo then table.insert(activeList, "Auto Slide") end\n        if config.vehicles and config.vehicles.godmode then table.insert(activeList, "Car Godmode") end\n        \n        if #activeList > 0 then\n            local startY = 50\n            for _, name in ipairs(activeList) do\n                local nSize = imgui.CalcTextSize(name)\n                local curX = sw - nSize.x - 22\n                \n                drawList:AddRectFilled(imgui.ImVec2(curX - 6, startY), imgui.ImVec2(sw - 14, startY + nSize.y + 2), imgui.ImColor(10, 11, 16, 160):GetU32(), 3.0)\n                drawList:AddText(imgui.ImVec2(curX, startY + 1), imgui.ImColor(230, 238, 255, 240):GetU32(), name)\n                \n                startY = startY + nSize.y + 6\n            end\n        end\n    end\nend\n\nreturn HUD\n', 'somalia/aim.lua': '--[[\n    Somalia - Legit Aimbot & Silent Aim Module\n    Renderização separada e precisa de FOV para Aimbot e Silent Aim\n]]\n\nlocal okImgui, imgui = pcall(require, \'imgui\')\nlocal okMemory, memory = pcall(require, \'memory\')\n\nlocal Aim = {\n    currentTarget = nil,\n    lastFovLogTick = 0,\n    lastSilentFovLogTick = 0,\n    lastAimLogTick = 0\n}\n\nlocal boneIds = {\n    [0] = 8, -- Head\n    [1] = 7, -- Neck\n    [2] = 3, -- Chest\n    [3] = 1  -- Pelvis\n}\n\n-- 1. IDENTIFICAÇÃO CENTRALIZADA DA ARMA ATUAL\nfunction Aim.getCurrentWeaponId()\n    if isSampLoaded() and (not isSampAvailable() or not sampIsLocalPlayerSpawned() or sampIsDialogActive()) then\n        return 0\n    end\n    if doesCharExist(playerPed) and not isCharDead(playerPed) then\n        return getCurrentCharWeapon(playerPed)\n    end\n    return 0\nend\n\nlocal function getScreenCenter()\n    local sw, sh = getScreenResolution()\n    return sw / 2, sh / 2\nend\n\nlocal function normalizeAngle(a)\n    while a > math.pi do a = a - 2 * math.pi end\n    while a < -math.pi do a = a + 2 * math.pi end\n    return a\nend\n\nlocal function getWeaponConfig(config, prefix, wId)\n    if not config then return nil end\n    local key = prefix .. "_w_" .. tostring(wId)\n    if type(config[key]) == \'table\' then\n        return config[key]\n    end\n    if config[prefix] and type(config[prefix].weapons) == \'table\' then\n        return config[prefix].weapons[wId] or config[prefix].weapons[tostring(wId)]\n    end\n    return nil\nend\n\n-- 2. RENDERIZAÇÃO SEGURA DO CÍRCULO DE FOV (AIMBOT & SILENT AIM INDEPENDENTES)\nfunction Aim.renderFovCircle(config, customDrawList)\n    if not okImgui or not config then return end\n    \n    -- Trava estrita contra execução antes do spawn ou em diálogos/login\n    if isSampLoaded() and (not isSampAvailable() or not sampIsLocalPlayerSpawned() or sampIsDialogActive()) then \n        return \n    end\n    if not doesCharExist(playerPed) or isCharDead(playerPed) then \n        return \n    end\n    \n    local wId = Aim.getCurrentWeaponId()\n    if wId == 0 then return end\n    \n    local drawList = customDrawList or (imgui.GetWindowDrawList and imgui.GetWindowDrawList())\n    if not drawList then return end\n    \n    local cx, cy = getScreenCenter()\n    local now = os.clock()\n\n    -- 2.1 FOV DO AIMBOT LEGIT (PRESERVADO INTACTO)\n    if config.aim and config.aim.globalEnabled ~= false then\n        local wAim = getWeaponConfig(config, "aim", wId)\n        if wAim and wAim.enabled and wAim.showFov then\n            local radiusAim = tonumber(wAim.fovSize) or 60\n            local fovColorAim = imgui.ImColor(0, 140, 255, 120):GetU32() -- Azul Neon Aimbot\n            \n            drawList:AddCircle(imgui.ImVec2(cx, cy), radiusAim, fovColorAim, 36)\n            \n            if (now - Aim.lastFovLogTick) >= 2.0 then\n                Aim.lastFovLogTick = now\n                print(string.format("[SOMALIA][FOV] ativo | arma: %d | raio: %.1f px | desenhado", wId, radiusAim))\n            end\n        end\n    end\n\n    -- 2.2 FOV DO SILENT AIM (INDEPENDENTE E COM IDENTIFICAÇÃO VISUAL PRÓPRIA)\n    if config.silent and config.silent.globalEnabled ~= false then\n        local wSil = getWeaponConfig(config, "silent", wId)\n        if wSil and wSil.enabled and wSil.showFov then\n            local radiusSil = tonumber(wSil.fovSize) or 70\n            local fovColorSil = imgui.ImColor(255, 80, 80, 120):GetU32() -- Vermelho/Laranja Silent FOV\n            \n            drawList:AddCircle(imgui.ImVec2(cx, cy), radiusSil, fovColorSil, 36)\n            \n            if (now - Aim.lastSilentFovLogTick) >= 2.0 then\n                Aim.lastSilentFovLogTick = now\n                print(string.format("[SOMALIA][SILENT FOV] enabled | weapon: %d | radius: %.1f | draw called", wId, radiusSil))\n            end\n        end\n    end\nend\n\n-- 3. AQUISIÇÃO DO MELHOR ALVO\nfunction Aim.getBestTarget(wCfg)\n    if isSampLoaded() and (not isSampAvailable() or not sampIsLocalPlayerSpawned() or sampIsDialogActive()) then return nil end\n    if not doesCharExist(playerPed) or isCharDead(playerPed) or not wCfg then return nil end\n    \n    local px, py, pz = getCharCoordinates(playerPed)\n    local cx, cy = getScreenCenter()\n    \n    local bestPed = nil\n    local minFovDist = tonumber(wCfg.fovSize) or 60\n    local maxDist3D = tonumber(wCfg.maxDist) or 150\n    local targetBoneId = boneIds[wCfg.hitbox] or 8\n    \n    for _, handle in ipairs(getAllChars()) do\n        if handle ~= playerPed and doesCharExist(handle) and not isCharDead(handle) then\n            local isNpc = not isSampLoaded() or not isSampfuncsLoaded() or (sampGetPlayerIdByCharHandle(handle) == nil)\n            \n            if not isNpc or wCfg.allowNpc then\n                local tx, ty, tz = getCharCoordinates(handle)\n                local dist3D = getDistanceBetweenCoords3d(px, py, pz, tx, ty, tz)\n                \n                if dist3D <= maxDist3D then\n                    local bx, by, bz = tx, ty, tz + 0.6\n                    local ptr = getCharPointer(handle)\n                    if ptr and ptr ~= 0 then\n                        pcall(function()\n                            bx, by, bz = getPedBonePosition(handle, targetBoneId)\n                        end)\n                    end\n                    \n                    local res, sx, sy = convert3DCoordsToScreen(bx, by, bz)\n                    if res then\n                        local fovDist = math.sqrt((sx - cx)^2 + (sy - cy)^2)\n                        if fovDist <= minFovDist then\n                            local isVisible = true\n                            if wCfg.visibleCheck then\n                                isVisible = processLineOfSight(px, py, pz + 0.7, bx, by, bz, true, false, false, true, false, false, false, false)\n                            end\n                            \n                            if isVisible then\n                                minFovDist = fovDist\n                                bestPed = handle\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end\n    return bestPed\nend\n\n-- 4. PROCESSAMENTO DO AIMBOT (DESATIVADO NESTA ETAPA DE TESTE VISUAL)\nfunction Aim.process(config)\n    Aim.currentTarget = nil\n    return\nend\n\nreturn Aim\n', 'somalia/visuals.lua': '--[[\n    Somalia - Visuals & ESP Module\n    Renderização DirectX com cálculo robusto de 3D->2D, suporte a múltiplos peds e teste visual imediato\n]]\n\nlocal okImgui, imgui = pcall(require, \'imgui\')\n\nlocal Visuals = {\n    lastLogTick = 0\n}\n\n-- Mapa dos ossos do esqueleto GTA SA\nlocal skeletonPairs = {\n    {8, 7},   -- Cabeça -> Pescoço\n    {7, 3},   -- Pescoço -> Tronco\n    {3, 1},   -- Tronco -> Pélvis\n    {7, 5},   -- Pescoço -> Ombro Esq\n    {5, 4},   -- Ombro Esq -> Cotovelo Esq\n    {4, 34},  -- Cotovelo Esq -> Mão Esq\n    {7, 6},   -- Pescoço -> Ombro Dir\n    {6, 7},   -- Ombro Dir -> Cotovelo Dir\n    {7, 24},  -- Cotovelo Dir -> Mão Dir\n    {1, 42},  -- Pélvis -> Joelho Esq\n    {42, 41}, -- Joelho Esq -> Pé Esq\n    {1, 52},  -- Pélvis -> Joelho Dir\n    {52, 51}  -- Joelho Dir -> Pé Dir\n}\n\nlocal function drawCornerBox(drawList, x, y, w, h, color)\n    local lineW = math.floor(w * 0.28)\n    local lineH = math.floor(h * 0.22)\n    -- Top Left\n    drawList:AddLine(imgui.ImVec2(x, y), imgui.ImVec2(x + lineW, y), color, 1.5)\n    drawList:AddLine(imgui.ImVec2(x, y), imgui.ImVec2(x, y + lineH), color, 1.5)\n    -- Top Right\n    drawList:AddLine(imgui.ImVec2(x + w, y), imgui.ImVec2(x + w - lineW, y), color, 1.5)\n    drawList:AddLine(imgui.ImVec2(x + w, y), imgui.ImVec2(x + w, y + lineH), color, 1.5)\n    -- Bottom Left\n    drawList:AddLine(imgui.ImVec2(x, y + h), imgui.ImVec2(x + lineW, y + h), color, 1.5)\n    drawList:AddLine(imgui.ImVec2(x, y + h), imgui.ImVec2(x, y + h - lineH), color, 1.5)\n    -- Bottom Right\n    drawList:AddLine(imgui.ImVec2(x + w, y + h), imgui.ImVec2(x + w - lineW, y + h), color, 1.5)\n    drawList:AddLine(imgui.ImVec2(x + w, y + h), imgui.ImVec2(x + w, y + h - lineH), color, 1.5)\nend\n\nfunction Visuals.render(config, customDrawList)\n    if not okImgui or not config or not config.visuals or not config.visuals.enabled then return end\n    \n    -- Proteção rigorosa contra execução antes do spawn ou durante conexão / login / diálogos\n    if isSampLoaded() and (not isSampAvailable() or not sampIsLocalPlayerSpawned() or sampIsDialogActive()) then \n        return \n    end\n    if not doesCharExist(playerPed) or isCharDead(playerPed) then \n        return \n    end\n    \n    local drawList = customDrawList or (imgui.GetWindowDrawList and imgui.GetWindowDrawList())\n    if not drawList then return end\n\n    local px, py, pz = getCharCoordinates(playerPed)\n    local sw, sh = getScreenResolution()\n    local maxDist = tonumber(config.visuals.maxDistance) or 250\n    \n    -- 0. INDICADOR VISUAL MÍNIMO DE TESTE (Prova que a camada de desenho do ImGui está ativa na tela)\n    local testText = "[ SOMALIA ESP ACTIVE ]"\n    local testSize = imgui.CalcTextSize(testText)\n    local testX = (sw - testSize.x) / 2\n    local testY = 25\n    drawList:AddRectFilled(imgui.ImVec2(testX - 6, testY - 2), imgui.ImVec2(testX + testSize.x + 6, testY + testSize.y + 2), imgui.ImColor(10, 15, 25, 200):GetU32(), 4.0)\n    drawList:AddText(imgui.ImVec2(testX, testY), imgui.ImColor(0, 200, 255, 255):GetU32(), testText)\n\n    local pedsEncontrados = 0\n    local pedsValidos = 0\n    local coordsValidas = 0\n    local boxesDesenhadas = 0\n    \n    for _, handle in ipairs(getAllChars()) do\n        pedsEncontrados = pedsEncontrados + 1\n        \n        -- Validação de ped válido: exclui o jogador local e peds mortos\n        if handle ~= playerPed and doesCharExist(handle) and not isCharDead(handle) then\n            pedsValidos = pedsValidos + 1\n            local tx, ty, tz = getCharCoordinates(handle)\n            local dist = getDistanceBetweenCoords3d(px, py, pz, tx, ty, tz)\n            \n            if dist <= maxDist then\n                -- Conversão 3D -> 2D robusta (Pé, Cabeça e Centro)\n                local resFoot, fx, fy = convert3DCoordsToScreen(tx, ty, tz - 0.95)\n                local resHead, hx, hy = convert3DCoordsToScreen(tx, ty, tz + 0.85)\n                local resCenter, cx, cy = convert3DCoordsToScreen(tx, ty, tz)\n                \n                if resFoot or resHead or resCenter then\n                    coordsValidas = coordsValidas + 1\n                    \n                    local boxH = 0\n                    local boxW = 0\n                    local boxX = 0\n                    local boxY = 0\n                    \n                    if resFoot and resHead then\n                        boxH = math.abs(fy - hy)\n                        boxW = boxH * 0.52\n                        boxX = fx - (boxW / 2)\n                        boxY = math.min(fy, hy)\n                    elseif resCenter then\n                        boxH = math.max(12, (sh / math.max(1, dist)) * 1.15)\n                        boxW = boxH * 0.52\n                        boxX = cx - (boxW / 2)\n                        boxY = cy - (boxH / 2)\n                        fx, fy = cx, cy + (boxH / 2)\n                    end\n                    \n                    if boxH > 4 and boxW > 2 then\n                        boxesDesenhadas = boxesDesenhadas + 1\n                        \n                        local isEnemy = true\n                        local colorBox = isEnemy and imgui.ImColor(255, 60, 60, 240):GetU32() or imgui.ImColor(0, 140, 255, 240):GetU32()\n                        local colorText = imgui.ImColor(245, 248, 255, 255):GetU32()\n                        \n                        -- 1. 2D Box / Corner Box ESP\n                        if config.visuals.cornerBox then\n                            drawCornerBox(drawList, boxX, boxY, boxW, boxH, colorBox)\n                        elseif config.visuals.boxEsp then\n                            drawList:AddRect(imgui.ImVec2(boxX, boxY), imgui.ImVec2(boxX + boxW, boxY + boxH), colorBox, 0.0)\n                        end\n                        \n                        -- 2. Snaplines\n                        if config.visuals.snaplines and resFoot then\n                            drawList:AddLine(imgui.ImVec2(sw / 2, sh), imgui.ImVec2(fx, fy), imgui.ImColor(255, 60, 60, 140):GetU32(), 1.0)\n                        end\n                        \n                        -- 3. Health Bar & Armor Bar\n                        local hp = getCharHealth(handle)\n                        local arm = getCharArmour(handle)\n                        \n                        if config.visuals.healthBar then\n                            local barX = boxX - 6\n                            local hpPercent = math.max(0, math.min(100, hp)) / 100.0\n                            local fillH = boxH * hpPercent\n                            drawList:AddRectFilled(imgui.ImVec2(barX, boxY), imgui.ImVec2(barX + 3, boxY + boxH), imgui.ImColor(20, 20, 20, 200):GetU32(), 0.0)\n                            drawList:AddRectFilled(imgui.ImVec2(barX, boxY + boxH - fillH), imgui.ImVec2(barX + 3, boxY + boxH), imgui.ImColor(30, 215, 96, 255):GetU32(), 0.0)\n                        end\n                        \n                        if config.visuals.armorBar and arm > 0 then\n                            local barX = boxX + boxW + 3\n                            local armPercent = math.max(0, math.min(100, arm)) / 100.0\n                            local fillH = boxH * armPercent\n                            drawList:AddRectFilled(imgui.ImVec2(barX, boxY), imgui.ImVec2(barX + 3, boxY + boxH), imgui.ImColor(20, 20, 20, 200):GetU32(), 0.0)\n                            drawList:AddRectFilled(imgui.ImVec2(barX, boxY + boxH - fillH), imgui.ImVec2(barX + 3, boxY + boxH), imgui.ImColor(230, 235, 255, 255):GetU32(), 0.0)\n                        end\n                        \n                        -- 4. Nickname & ID\n                        local label = ""\n                        if isSampLoaded() and isSampAvailable() then\n                            local res, id = sampGetPlayerIdByCharHandle(handle)\n                            if res then\n                                local nick = sampGetPlayerNickname(id) or "Player"\n                                if config.visuals.playerNames and config.visuals.playerId then\n                                    label = string.format("%s [%d]", nick, id)\n                                elseif config.visuals.playerNames then\n                                    label = nick\n                                elseif config.visuals.playerId then\n                                    label = string.format("[%d]", id)\n                                end\n                            end\n                        end\n                        \n                        if label ~= "" then\n                            local tSize = imgui.CalcTextSize(label)\n                            drawList:AddText(imgui.ImVec2(boxX + (boxW - tSize.x) / 2, boxY - tSize.y - 3), colorText, label)\n                        end\n                        \n                        -- 5. Distância\n                        if config.visuals.distance then\n                            local distText = string.format("%dm", math.floor(dist))\n                            local dSize = imgui.CalcTextSize(distText)\n                            drawList:AddText(imgui.ImVec2(boxX + (boxW - dSize.x) / 2, boxY + boxH + 3), imgui.ImColor(180, 195, 220, 240):GetU32(), distText)\n                        end\n                        \n                        -- 6. Skeleton ESP com validação de ponteiro\n                        if config.visuals.skeleton then\n                            local ptr = getCharPointer(handle)\n                            if ptr and ptr ~= 0 then\n                                for _, pair in ipairs(skeletonPairs) do\n                                    local okBone, errBone = pcall(function()\n                                        local b1x, b1y, b1z = getPedBonePosition(handle, pair[1])\n                                        local b2x, b2y, b2z = getPedBonePosition(handle, pair[2])\n                                        local r1, s1x, s1y = convert3DCoordsToScreen(b1x, b1y, b1z)\n                                        local r2, s2x, s2y = convert3DCoordsToScreen(b2x, b2y, b2z)\n                                        if r1 and r2 then\n                                            drawList:AddLine(imgui.ImVec2(s1x, s1y), imgui.ImVec2(s2x, s2y), imgui.ImColor(255, 255, 255, 200):GetU32(), 1.0)\n                                        end\n                                    end)\n                                    if not okBone and errBone then\n                                        print("[SOMALIA][ESP ERRO SKELETON] " .. tostring(errBone))\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end\n    \n    local now = os.clock()\n    if (now - Visuals.lastLogTick) >= 2.0 then\n        Visuals.lastLogTick = now\n        print("[SOMALIA][ESP] ENABLED")\n        print(string.format("[SOMALIA][ESP] render chamado | peds encontrados: %d | peds validos: %d | coords validas: %d | boxes desenhadas: %d", \n            pedsEncontrados, pedsValidos, coordsValidas, boxesDesenhadas))\n    end\nend\n\nreturn Visuals\n', 'somalia/player.lua': '--[[\n    Somalia - Player & Movement Module\n    Preserva rigorosamente a lógica original de C-Slide e Auto-Slide (Quick Switch)\n    Proteção total contra execução antes do spawn no SA-MP\n]]\n\nlocal okVkeys, vkeys = pcall(require, \'vkeys\')\nlocal okMemory, memory = pcall(require, \'memory\')\n\nlocal Player = {\n    mirandoAnteriormente = false,\n    tempoUltimoTiro = 0,\n    executandoAcao = false,\n    idParaChave = {\n        [34] = "margem_snp",\n        [24] = "margem_desert",\n        [31] = "margem_m4",\n        [30] = "margem_ak",\n        [25] = "margem_shot"\n    }\n}\n\nfunction Player.process(config)\n    if not config or not config.player then return end\n    \n    -- Proteção rigorosa contra execução antes do spawn ou durante conexão\n    if isSampLoaded() and (not isSampAvailable() or not sampIsLocalPlayerSpawned()) then\n        Player.mirandoAnteriormente = false\n        Player.executandoAcao = false\n        return\n    end\n    \n    if not doesCharExist(playerPed) or isCharDead(playerPed) or isCharInAnyCar(playerPed) then\n        Player.mirandoAnteriormente = false\n        Player.executandoAcao = false\n        return\n    end\n    \n    -- 1. INFINITE STAMINA (Trava a stamina máxima em memória)\n    if config.player.infiniteStamina and okMemory then\n        pcall(function()\n            memory.setfloat(0xB7CEE4, 100.0)\n        end)\n    end\n    \n    -- 2. NO FALL DAMAGE (Imunidade a dano por impacto/queda)\n    if config.player.noFallDamage then\n        pcall(function()\n            setCharProofs(playerPed, false, false, false, true, false)\n        end)\n    end\n    \n    -- 3. SPRINT SPEED MULTIPLIER\n    if config.player.sprintSpeed and config.player.sprintSpeed > 1.05 then\n        local isSprinting = isKeyDown(0x20) or isKeyDown(0x10) -- Space ou Shift\n        if isSprinting then\n            pcall(function()\n                setCharAnimSpeed(playerPed, "run_civi", config.player.sprintSpeed)\n                setCharAnimSpeed(playerPed, "sprint_civi", config.player.sprintSpeed)\n                setCharAnimSpeed(playerPed, "run_player", config.player.sprintSpeed)\n                setCharAnimSpeed(playerPed, "sprint_panic", config.player.sprintSpeed)\n            end)\n        end\n    end\n    \n    -- 4. LÓGICA ORIGINAL DE C-SLIDE E AUTO-SLIDE (PRESERVADA 1:1)\n    if config.player.scriptAtivo then\n        if isCharShooting(playerPed) or isKeyDown(0x01) then -- Mouse 1\n            Player.tempoUltimoTiro = os.clock()\n        end\n\n        local mirandoAgora = isKeyDown(0x02) -- Mouse 2\n\n        -- Detecção instantânea da transição: MIRANDO -> SOLTOU A MIRA\n        if Player.mirandoAnteriormente and not mirandoAgora then\n            if not sampIsChatInputActive() and not sampIsDialogActive() then\n                local armaAtual = getCurrentCharWeapon(playerPed)\n                local chaveArma = Player.idParaChave[armaAtual]\n                local margem = (chaveArma and config.player[chaveArma]) or 0\n                local segurandoMovimento = isKeyDown(0x41) or isKeyDown(0x44) or isKeyDown(0x57) or isKeyDown(0x53) or (getCharSpeed(playerPed) > 0.4) -- A, D, W, S\n\n                if not Player.executandoAcao then\n                    Player.executandoAcao = true\n                    lua_thread.create(function()\n                        local tempoPassado = (os.clock() - Player.tempoUltimoTiro) * 1000\n                        if margem > 0 and tempoPassado < margem then\n                            wait(margem - tempoPassado)\n                        end\n\n                        -- 1. C-SLIDE FLUIDO (Agachar e Deslizar)\n                        if config.player.cSlideAtivo and segurandoMovimento then\n                            local duracao = math.max(10, config.player.duracaoC or 10)\n                            setGameKeyState(18, 255)\n                            setGameKeyState(1, 255)\n                            pcall(function() setVirtualKeyDown(0x43, true) end) -- C\n                            wait(duracao)\n                            setGameKeyState(18, 0)\n                            setGameKeyState(1, 0)\n                            pcall(function() setVirtualKeyDown(0x43, false) end)\n                        end\n\n                        -- 2. AUTO SLIDE / TROCA RÁPIDA PARA O SOCO (SLOT 0)\n                        if config.player.autoSlideAtivo and okMemory then\n                            local delayTroca = config.player.delayTroca or 0\n                            if delayTroca > 0 then wait(delayTroca) end\n\n                            if doesCharExist(playerPed) and not isCharDead(playerPed) and not isCharInAnyCar(playerPed) and not sampIsChatInputActive() and not sampIsDialogActive() then\n                                local ptr = getCharPointer(playerPed)\n                                if ptr and ptr ~= 0 then\n                                    local curSlot = memory.getuint8(ptr + 0x718)\n                                    if curSlot > 0 then\n                                        memory.setuint8(ptr + 0x718, 0)\n                                        setGameKeyState(16, 255)\n                                        pcall(function() setVirtualKeyDown(0x51, true) end) -- Q\n                                        wait(30)\n                                        setGameKeyState(16, 0)\n                                        pcall(function() setVirtualKeyDown(0x51, false) end)\n                                    end\n                                end\n                            end\n                        end\n\n                        wait(30)\n                        Player.executandoAcao = false\n                    end)\n                end\n            end\n        end\n        Player.mirandoAnteriormente = mirandoAgora\n    else\n        Player.mirandoAnteriormente = false\n    end\nend\n\nreturn Player\n', 'somalia/vehicles.lua': '--[[\n    Somalia - Vehicles Module\n    Recursos para veículos: Speed Boost, Instant Repair, Flip Car, Godmode e Engine Always On\n]]\n\nlocal Vehicles = {\n    lastRepairPress = 0,\n    lastFlipPress = 0\n}\n\nfunction Vehicles.process(config)\n    if not config or not config.vehicles then return end\n    if isCharDead(playerPed) or not isCharInAnyCar(playerPed) then return end\n    \n    local car = storeCarCharIsInNoSave(playerPed)\n    if not car or car == 0 then return end\n    \n    -- 1. VEHICLE GODMODE\n    if config.vehicles.godmode then\n        pcall(function()\n            setCarProofs(car, true, true, true, true, true)\n        end)\n    end\n    \n    -- 2. ENGINE ALWAYS ON\n    if config.vehicles.engineAlwaysOn then\n        pcall(function()\n            setCarEngineOn(car, true)\n        end)\n    end\n    \n    -- 3. SPEED BOOST\n    if config.vehicles.speedBoost and not sampIsChatInputActive() and not sampIsDialogActive() then\n        local boostKey = config.vehicles.speedBoostKey or 0x10 -- Shift\n        if isKeyDown(boostKey) then\n            pcall(function()\n                local mult = config.vehicles.speedMultiplier or 1.3\n                local vx, vy, vz = getCarSpeedVector(car)\n                setCarSpeedVector(car, vx * mult, vy * mult, vz)\n            end)\n        end\n    end\n    \n    -- 4. INSTANT REPAIR (KEYBIND)\n    if config.vehicles.instantRepair and not sampIsChatInputActive() and not sampIsDialogActive() then\n        local repairKey = config.vehicles.instantRepairKey or 0x52 -- R\n        local now = os.clock()\n        if isKeyDown(repairKey) and (now - Vehicles.lastRepairPress) > 0.8 then\n            Vehicles.lastRepairPress = now\n            pcall(function()\n                fixCar(car)\n                setCarHealth(car, 1000)\n            end)\n        end\n    end\n    \n    -- 5. FLIP CAR (KEYBIND)\n    if config.vehicles.flipCar and not sampIsChatInputActive() and not sampIsDialogActive() then\n        local flipKey = config.vehicles.flipCarKey or 0x58 -- X\n        local now = os.clock()\n        if isKeyDown(flipKey) and (now - Vehicles.lastFlipPress) > 0.8 then\n            Vehicles.lastFlipPress = now\n            pcall(function()\n                local heading = getCarHeading(car)\n                setCarHeading(car, heading)\n                local cx, cy, cz = getCarCoordinates(car)\n                setCarCoordinates(car, cx, cy, cz + 0.6)\n            end)\n        end\n    end\nend\n\nreturn Vehicles\n', 'somalia/world.lua': '--[[\n    Somalia - World Module\n    Controle em tempo real de Horário e Clima com trava persistente\n]]\n\nlocal World = {}\n\nfunction World.process(config)\n    if not config or not config.world then return end\n    \n    -- 1. CUSTOM TIME\n    if config.world.customTimeEnabled then\n        local hour = config.world.customHour or 12\n        local minute = config.world.customMinute or 0\n        pcall(function()\n            setTimeOfDay(hour, minute)\n        end)\n    end\n    \n    -- 2. CUSTOM WEATHER\n    if config.world.customWeatherEnabled then\n        local wId = config.world.weatherId or 1\n        pcall(function()\n            forceWeatherNow(wId)\n        end)\n    end\nend\n\nreturn World\n', 'somalia/misc.lua': "--[[\n    Somalia - Misc & Exploits Module\n    No Recoil, No Spread e Fast Reload com patches de memória seguros\n]]\n\nlocal okMemory, memory = pcall(require, 'memory')\n\nlocal Misc = {}\n\nfunction Misc.process(config)\n    if not config or not config.misc or not okMemory then return end\n    if isCharDead(playerPed) then return end\n    \n    -- 1. NO RECOIL / NO SPREAD\n    if config.misc.noRecoil or config.misc.noSpread then\n        pcall(function()\n            local camPtr = 0xB6F248\n            if camPtr and camPtr ~= 0 then\n                memory.setfloat(0xB7CD98, 0.0) -- Camera Shake\n            end\n        end)\n    end\n    \n    -- 2. FAST RELOAD\n    if config.misc.fastReload then\n        if isCharShooting(playerPed) then\n            pcall(function()\n                local weapon = getCurrentCharWeapon(playerPed)\n                local ammo = getAmmoInCharWeapon(playerPed, weapon)\n                if ammo <= 1 then\n                    setCharAmmo(playerPed, weapon, 999)\n                end\n            end)\n        end\n    end\nend\n\nreturn Misc\n", 'main.lua': '--[[\n    SOMALIA - Professional Showcase Edition\n    Main Entrypoint & SML UI Architecture\n    Reativação Segura e Isolada de ESP e FOV Circle (Aimbot & Silent FOV)\n]]\n\n-- Configura caminho de busca dos módulos locais\nlocal workDir = getWorkingDirectory()\npackage.path = workDir .. "\\\\?.lua;" .. workDir .. "\\\\somalia\\\\?.lua;" .. workDir .. "\\\\lib\\\\?.lua;" .. package.path\n\nlocal function safeRequire(modName, fallbackName)\n    local ok, mod = pcall(require, modName)\n    if not ok and fallbackName then\n        ok, mod = pcall(require, fallbackName)\n    end\n    if not ok then\n        print("[SOMALIA AVISO] Falha ao carregar modulo: " .. tostring(modName) .. " (" .. tostring(mod) .. ")")\n        return false, {}\n    end\n    return true, mod\nend\n\n-- =========================================================================\n-- CONTROLE DE ISOLAMENTO DE MÓDULOS\n-- =========================================================================\nlocal ENABLE_VISUALS_RUNTIME = true   -- Reativa ESP e FOVs (Aimbot & Silent) com gating estrito de spawn\nlocal ENABLE_GAMEPLAY_RUNTIME = false -- Mantém Aim, Player, Vehicles, World e Misc desativados\n\n-- Carregamento seguro dos módulos do Somalia\nlocal okTheme, Theme = safeRequire(\'somalia.theme\', \'theme\')\nlocal okNotifications, Notifications = safeRequire(\'somalia.notifications\', \'notifications\')\nlocal okKeybinds, Keybinds = safeRequire(\'somalia.keybinds\', \'keybinds\')\nlocal okConfig, Config = safeRequire(\'somalia.config\', \'config\')\nlocal okHUD, HUD = safeRequire(\'somalia.hud\', \'hud\')\nlocal okAim, Aim = safeRequire(\'somalia.aim\', \'aim\')\nlocal okVisuals, Visuals = safeRequire(\'somalia.visuals\', \'visuals\')\nlocal okPlayer, Player = safeRequire(\'somalia.player\', \'player\')\nlocal okVehicles, Vehicles = safeRequire(\'somalia.vehicles\', \'vehicles\')\nlocal okWorld, World = safeRequire(\'somalia.world\', \'world\')\nlocal okMisc, Misc = safeRequire(\'somalia.misc\', \'misc\')\n\nlocal okImgui, imgui = pcall(require, \'imgui\')\n\n-- Configuração segura de codificação UTF-8 para acentuação no ImGui\nlocal u8 = function(str) return str end\nlocal okEncoding, encoding = pcall(require, \'encoding\')\nif okEncoding then\n    encoding.default = \'CP1252\'\n    u8 = encoding.UTF8\nend\n\n-- Inicialização de Configurações, Temas e Notificações\nif okConfig and Config.init then Config.init() end\nif okNotifications and Notifications.init and okTheme then Notifications.init(Theme) end\nif okTheme and Theme.initFonts then Theme.initFonts() end\n\n-- Variáveis de controle de interface ImGui\nlocal janelaAberta = okImgui and imgui.ImBool(false) or { v = false }\n\n-- Navegação das Abas\nlocal abaLateral = 1 -- 1 = Aimbot, 2 = Visuals, 3 = World, 4 = Vehicles, 5 = Players, 6 = Exploits, 7 = Configs\nlocal lastAbaLateral = 1\nlocal tabAlpha = 1.0\n\n-- Animações dos componentes\nlocal animCheckboxes = {}\nlocal animNav = {}\nlocal animCombos = {}\n\nlocal hitboxOptions = { "Head", "Neck", "Chest", "Pelvis" }\nlocal weaponNames = {\n    "Desert Eagle", "M4", "AK-47", "Shotgun", "Sawnoff",\n    "Combat Shotgun", "MP5", "Tec-9", "Micro Uzi", "Sniper Rifle",\n    "Country Rifle", "Pistol (Colt 45)", "Silenced 9mm"\n}\nlocal weaponIds = {\n    24, 31, 30, 25, 26,\n    27, 29, 32, 28, 34,\n    33, 22, 23\n}\n\nlocal keyWasDown = {}\nlocal function isKeyJustPressed(key)\n    if isSampLoaded() and (sampIsDialogActive() or sampIsChatInputActive()) then\n        return false\n    end\n    if isKeyDown(key) then\n        if not keyWasDown[key] then\n            keyWasDown[key] = true\n            return true\n        end\n    else\n        keyWasDown[key] = false\n    end\n    return false\nend\n\n-- Validação de segurança: apenas quando o jogador está efetivamente spawnado e livre de login/diálogos\nlocal function isPlayerReady()\n    if isSampLoaded() then\n        if not isSampAvailable() or not sampIsLocalPlayerSpawned() or sampIsDialogActive() then\n            return false\n        end\n    end\n    return doesCharExist(playerPed) and not isCharDead(playerPed)\nend\n\n-------------------------------------------------------------------------\n-- COMPONENTES GRÁFICOS VETORIAIS 1:1\n-------------------------------------------------------------------------\n\n-- 1. Header com Perfil (Username, Owner, Avatar circular no canto superior direito)\nlocal function DrawHeaderProfile(headerX, headerY, name, role)\n    local drawList = imgui.GetWindowDrawList()\n    local txtNameSize = imgui.CalcTextSize(name)\n    local txtRoleSize = imgui.CalcTextSize(role)\n    \n    local avRadius = 15.0\n    local avCx = headerX - avRadius - 6\n    local avCy = headerY + 18\n    \n    local textRightEdge = avCx - avRadius - 10\n    \n    -- Nome do Usuário\n    drawList:AddText(imgui.ImVec2(textRightEdge - txtNameSize.x, headerY + 5), imgui.ImColor(255, 255, 255, 255):GetU32(), name)\n    -- Cargo / Subtítulo\n    drawList:AddText(imgui.ImVec2(textRightEdge - txtRoleSize.x, headerY + 22), imgui.ImColor(135, 148, 170, 255):GetU32(), role)\n    \n    -- Avatar circular azul neon com anel brilhante\n    drawList:AddCircleFilled(imgui.ImVec2(avCx, avCy), avRadius, imgui.ImColor(0, 128, 255, 255):GetU32())\n    drawList:AddCircle(imgui.ImVec2(avCx, avCy), avRadius, imgui.ImColor(80, 180, 255, 255):GetU32(), 24)\n    \n    -- Silhueta branca do avatar\n    drawList:AddCircleFilled(imgui.ImVec2(avCx, avCy - 4.2), 4.6, imgui.ImColor(255, 255, 255, 255):GetU32())\n    drawList:AddTriangleFilled(imgui.ImVec2(avCx - 7.5, avCy + 11), imgui.ImVec2(avCx, avCy + 2), imgui.ImVec2(avCx + 7.5, avCy + 11), imgui.ImColor(255, 255, 255, 255):GetU32())\nend\n\n-- 2. Botão da Sidebar Vertical com Animação Suave e Ícones Idênticos ao Vídeo\nlocal function DrawSidebarItem(id, label, iconType, isActive)\n    if animNav[id] == nil then animNav[id] = isActive and 1.0 or 0.0 end\n    local drawList = imgui.GetWindowDrawList()\n    local pos = imgui.GetCursorScreenPos()\n    local w, h = 135, 34\n    \n    imgui.PushID(id)\n    local clicked = imgui.InvisibleButton("##" .. id, imgui.ImVec2(w, h))\n    local hovered = imgui.IsItemHovered()\n    imgui.PopID()\n    \n    local target = isActive and 1.0 or (hovered and 0.45 or 0.0)\n    animNav[id] = animNav[id] + (target - animNav[id]) * 0.22\n    local val = animNav[id]\n    \n    local r = math.floor(10 + (22 - 10) * val)\n    local g = math.floor(14 + (38 - 14) * val)\n    local b = math.floor(22 + (70 - 22) * val)\n    local a = math.floor(0 + (255 - 0) * val)\n    local bgColor = imgui.ImColor(r, g, b, a):GetU32()\n    \n    drawList:AddRectFilled(pos, imgui.ImVec2(pos.x + w, pos.y + h), bgColor, Theme.Rounding.Button)\n    if val > 0.02 then\n        local bA = math.floor(val * 220)\n        drawList:AddRect(pos, imgui.ImVec2(pos.x + w, pos.y + h), imgui.ImColor(0, 128, 255, bA):GetU32(), Theme.Rounding.Button)\n    end\n    \n    local ir = math.floor(120 + (0 - 120) * val)\n    local ig = math.floor(135 + (140 - 135) * val)\n    local ib = math.floor(155 + (255 - 155) * val)\n    local iconColor = (hovered and not isActive) and imgui.ImColor(210, 225, 255, 255):GetU32() or imgui.ImColor(ir, ig, ib, 255):GetU32()\n    \n    local icx = pos.x + 18\n    local icy = pos.y + (h / 2)\n    \n    if iconType == "aimbot" then\n        drawList:AddCircle(imgui.ImVec2(icx, icy), 6.5, iconColor, 16)\n        drawList:AddCircle(imgui.ImVec2(icx, icy), 2.5, iconColor, 12)\n        drawList:AddLine(imgui.ImVec2(icx - 8, icy), imgui.ImVec2(icx - 4, icy), iconColor, 1.4)\n        drawList:AddLine(imgui.ImVec2(icx + 4, icy), imgui.ImVec2(icx + 8, icy), iconColor, 1.4)\n        drawList:AddLine(imgui.ImVec2(icx, icy - 8), imgui.ImVec2(icx, icy - 4), iconColor, 1.4)\n        drawList:AddLine(imgui.ImVec2(icx, icy + 4), imgui.ImVec2(icx, icy + 8), iconColor, 1.4)\n    elseif iconType == "visuals" then\n        drawList:AddCircle(imgui.ImVec2(icx, icy), 6.0, iconColor, 16)\n        drawList:AddCircleFilled(imgui.ImVec2(icx, icy), 2.4, iconColor)\n    elseif iconType == "world" then\n        drawList:AddCircle(imgui.ImVec2(icx, icy), 6.5, iconColor, 16)\n        drawList:AddLine(imgui.ImVec2(icx - 6.5, icy), imgui.ImVec2(icx + 6.5, icy), iconColor, 1.2)\n        drawList:AddLine(imgui.ImVec2(icx, icy - 6.5), imgui.ImVec2(icx + 6.5, icy), iconColor, 1.2)\n        drawList:AddCircle(imgui.ImVec2(icx, icy), 3.5, iconColor, 12)\n    elseif iconType == "vehicles" then\n        drawList:AddRect(imgui.ImVec2(icx - 6, icy - 3), imgui.ImVec2(icx + 6, icy + 4), iconColor, 2.0)\n        drawList:AddCircleFilled(imgui.ImVec2(icx - 4, icy + 4), 1.8, iconColor)\n        drawList:AddCircleFilled(imgui.ImVec2(icx + 4, icy + 4), 1.8, iconColor)\n    elseif iconType == "players" then\n        drawList:AddCircleFilled(imgui.ImVec2(icx - 3, icy - 3), 2.5, iconColor)\n        drawList:AddCircleFilled(imgui.ImVec2(icx + 3, icy - 1), 2.0, iconColor)\n        drawList:AddTriangleFilled(imgui.ImVec2(icx - 6, icy + 5), imgui.ImVec2(icx - 3, icy + 1), imgui.ImVec2(icx, icy + 5), iconColor)\n    elseif iconType == "exploits" then\n        drawList:AddCircleFilled(imgui.ImVec2(icx, icy), 4.0, iconColor)\n        drawList:AddLine(imgui.ImVec2(icx - 5, icy - 3), imgui.ImVec2(icx + 5, icy + 3), iconColor, 1.2)\n        drawList:AddLine(imgui.ImVec2(icx - 5, icy + 3), imgui.ImVec2(icx + 5, icy - 3), iconColor, 1.2)\n        drawList:AddLine(imgui.ImVec2(icx - 6, icy), imgui.ImVec2(icx + 6, icy), iconColor, 1.2)\n    elseif iconType == "configs" then\n        drawList:AddRectFilled(imgui.ImVec2(icx - 6, icy - 4), imgui.ImVec2(icx - 2, icy - 2), iconColor, 1.0)\n        drawList:AddRect(imgui.ImVec2(icx - 6, icy - 2), imgui.ImVec2(icx + 6, icy + 5), iconColor, 2.0)\n    end\n    \n    local tr = math.floor(140 + (255 - 140) * val)\n    local tg = math.floor(150 + (255 - 150) * val)\n    local tb = math.floor(170 + (255 - 170) * val)\n    local textColor = (hovered and not isActive) and imgui.ImColor(230, 240, 255, 255):GetU32() or imgui.ImColor(tr, tg, tb, 255):GetU32()\n    \n    local txtSize = imgui.CalcTextSize(label)\n    drawList:AddText(imgui.ImVec2(pos.x + 36, pos.y + (h - txtSize.y) / 2), textColor, label)\n    \n    imgui.Spacing()\n    return clicked\nend\n\n-- 3. Checkbox com Animação Suave e Keybind Interativo\nlocal function DrawCheckboxWithKeybind(label, val_bool, key_code, id_str, onToggle, onKeyChange)\n    if animCheckboxes[id_str] == nil then animCheckboxes[id_str] = val_bool and 1.0 or 0.0 end\n    local target = val_bool and 1.0 or 0.0\n    animCheckboxes[id_str] = animCheckboxes[id_str] + (target - animCheckboxes[id_str]) * 0.28\n    local val = animCheckboxes[id_str]\n    \n    local drawList = imgui.GetWindowDrawList()\n    local pos = imgui.GetCursorScreenPos()\n    local availW = imgui.GetContentRegionAvailWidth()\n    local h = 22\n    local boxSize = 16\n    local boxX = pos.x + 2\n    local boxY = pos.y + (h - boxSize) / 2\n    \n    local btnW = key_code and (availW - 75) or availW\n    \n    imgui.PushID(id_str)\n    local clicked = imgui.InvisibleButton("##" .. id_str, imgui.ImVec2(btnW, h))\n    local hovered = imgui.IsItemHovered()\n    imgui.PopID()\n    \n    if clicked and onToggle then\n        onToggle(not val_bool)\n        if okConfig and Config.save then Config.save() end\n    end\n    \n    local r = math.floor(12 + (0 - 12) * val)\n    local g = math.floor(16 + (128 - 16) * val)\n    local b = math.floor(26 + (255 - 26) * val)\n    local bgCol = imgui.ImColor(r, g, b, 255):GetU32()\n    \n    local br = math.floor(36 + (0 - 36) * val)\n    local bg = math.floor(44 + (140 - 44) * val)\n    local bb = math.floor(60 + (255 - 60) * val)\n    local borderCol = hovered and imgui.ImColor(60, 140, 230, 255):GetU32() or imgui.ImColor(br, bg, bb, 255):GetU32()\n    \n    drawList:AddRectFilled(imgui.ImVec2(boxX, boxY), imgui.ImVec2(boxX + boxSize, boxY + boxSize), bgCol, Theme.Rounding.Checkbox)\n    drawList:AddRect(imgui.ImVec2(boxX, boxY), imgui.ImVec2(boxX + boxSize, boxY + boxSize), borderCol, Theme.Rounding.Checkbox)\n    \n    if val > 0.05 then\n        local checkAlpha = math.min(1.0, val * 1.6)\n        local checkCol = imgui.ImColor(255, 255, 255, math.floor(255 * checkAlpha)):GetU32()\n        local pt1 = imgui.ImVec2(boxX + 3.0, boxY + 8.0)\n        local pt2 = imgui.ImVec2(boxX + 6.0, boxY + 11.5)\n        local pt3 = imgui.ImVec2(boxX + 12.5, boxY + 4.5)\n        drawList:AddLine(pt1, pt2, checkCol, 1.8)\n        drawList:AddLine(pt2, pt3, checkCol, 1.8)\n    end\n    \n    local txtCol = hovered and imgui.ImColor(255, 255, 255, 255):GetU32() or imgui.ImColor(230, 235, 245, 255):GetU32()\n    local txtSize = imgui.CalcTextSize(label)\n    drawList:AddText(imgui.ImVec2(boxX + boxSize + 8, pos.y + (h - txtSize.y) / 2), txtCol, label)\n    \n    if key_code ~= nil and okKeybinds then\n        imgui.SameLine(availW - 70)\n        Keybinds.drawKeybindButton(id_str, key_code, onKeyChange, 68)\n    end\n    \n    imgui.Spacing()\n    return clicked\nend\n\nlocal function DrawVideoCheckbox(label, val_bool, id_str, onToggle)\n    return DrawCheckboxWithKeybind(label, val_bool, nil, id_str, onToggle, nil)\nend\n\n-- 4. Dropdown / Combobox Estilizado\nlocal function DrawVideoCombo(label, items, selected_idx, id_str, onSelect)\n    if animCombos[id_str] == nil then animCombos[id_str] = 0.0 end\n    \n    if label and label ~= "" then\n        imgui.TextColored(imgui.ImVec4(0.88, 0.91, 0.96, 1.0), label)\n    end\n    \n    local drawList = imgui.GetWindowDrawList()\n    local pos = imgui.GetCursorScreenPos()\n    local availW = imgui.GetContentRegionAvailWidth()\n    local w = availW - 4\n    local h = 26\n    local x = pos.x + 2\n    local y = pos.y\n    \n    imgui.PushID(id_str)\n    local clicked = imgui.InvisibleButton("##" .. id_str, imgui.ImVec2(w, h))\n    local hovered = imgui.IsItemHovered()\n    local active = imgui.IsItemActive()\n    imgui.PopID()\n    \n    if clicked then\n        local nextIdx = ((selected_idx or 0) + 1) % #items\n        if onSelect then onSelect(nextIdx) end\n        if okConfig and Config.save then Config.save() end\n    end\n    \n    local target = (hovered or active) and 1.0 or 0.0\n    animCombos[id_str] = animCombos[id_str] + (target - animCombos[id_str]) * 0.25\n    local val = animCombos[id_str]\n    \n    local r = math.floor(11 + (18 - 11) * val)\n    local g = math.floor(14 + (24 - 14) * val)\n    local b = math.floor(22 + (40 - 22) * val)\n    local bgCol = imgui.ImColor(r, g, b, 255):GetU32()\n    \n    local br = math.floor(28 + (0 - 28) * val)\n    local bg = math.floor(36 + (128 - 36) * val)\n    local bb = math.floor(52 + (255 - 52) * val)\n    local borderCol = imgui.ImColor(br, bg, bb, 255):GetU32()\n    \n    drawList:AddRectFilled(imgui.ImVec2(x, y), imgui.ImVec2(x + w, y + h), bgCol, Theme.Rounding.Button)\n    drawList:AddRect(imgui.ImVec2(x, y), imgui.ImVec2(x + w, y + h), borderCol, Theme.Rounding.Button)\n    \n    local currentText = items[(selected_idx or 0) + 1] or items[1]\n    local cTxtSize = imgui.CalcTextSize(currentText)\n    drawList:AddText(imgui.ImVec2(x + 10, y + (h - cTxtSize.y) / 2), imgui.ImColor(245, 248, 255, 255):GetU32(), currentText)\n    \n    local arrowX = x + w - 14\n    local arrowY = y + (h / 2)\n    local arrowCol = (hovered or active) and imgui.ImColor(0, 140, 255, 255):GetU32() or imgui.ImColor(130, 145, 170, 255):GetU32()\n    drawList:AddLine(imgui.ImVec2(arrowX - 4, arrowY - 2), imgui.ImVec2(arrowX, arrowY + 2), arrowCol, 1.6)\n    drawList:AddLine(imgui.ImVec2(arrowX, arrowY + 2), imgui.ImVec2(arrowX + 4, arrowY - 2), arrowCol, 1.6)\n    \n    imgui.Spacing()\n    return clicked\nend\n\n-- 5. Slider Idêntico ao Vídeo\nlocal function DrawVideoSlider(label, current_val, min_val, max_val, suffix, id_str, onChange)\n    local availW = imgui.GetContentRegionAvailWidth()\n    local w = availW - 4\n    local barH = 10\n    local rounding = 4.0\n    \n    local valStr = tostring(math.floor(current_val or min_val)) .. (suffix or "")\n    imgui.TextColored(imgui.ImVec4(0.88, 0.91, 0.96, 1.0), label)\n    local vTxtSize = imgui.CalcTextSize(valStr)\n    imgui.SameLine(availW - vTxtSize.x - 2)\n    imgui.TextColored(Theme.Colors.AccentPrimary, valStr)\n    \n    local drawList = imgui.GetWindowDrawList()\n    local pos = imgui.GetCursorScreenPos()\n    local x = pos.x + 2\n    local y = pos.y\n    \n    imgui.PushID(id_str)\n    local clicked = imgui.InvisibleButton("##" .. id_str, imgui.ImVec2(w, barH + 4))\n    local isItemActive = imgui.IsItemActive()\n    local isItemHovered = imgui.IsItemHovered()\n    imgui.PopID()\n    \n    local changed = false\n    if isItemActive then\n        local mpos = imgui.GetIO().MousePos\n        local fraction = math.max(0.0, math.min(1.0, (mpos.x - x) / w))\n        local newVal = math.floor(min_val + fraction * (max_val - min_val) + 0.5)\n        if newVal ~= current_val then\n            current_val = newVal\n            changed = true\n            if onChange then onChange(newVal) end\n            if okConfig and Config.save then Config.save() end\n        end\n    end\n    \n    local fraction = math.max(0.0, math.min(1.0, ((current_val or min_val) - min_val) / (max_val - min_val)))\n    local fillW = math.max(barH, fraction * w)\n    \n    local troughCol = imgui.ImColor(14, 16, 24, 255):GetU32()\n    local borderCol = (isItemActive or isItemHovered) and imgui.ImColor(40, 60, 95, 255):GetU32() or imgui.ImColor(26, 30, 42, 255):GetU32()\n    drawList:AddRectFilled(imgui.ImVec2(x, y + 2), imgui.ImVec2(x + w, y + 2 + barH), troughCol, rounding)\n    drawList:AddRect(imgui.ImVec2(x, y + 2), imgui.ImVec2(x + w, y + 2 + barH), borderCol, rounding)\n    \n    if fraction > 0.01 then\n        local fillCol = isItemActive and imgui.ImColor(0, 110, 230, 255):GetU32() or (isItemHovered and imgui.ImColor(20, 145, 255, 255):GetU32() or imgui.ImColor(0, 128, 255, 255):GetU32())\n        drawList:AddRectFilled(imgui.ImVec2(x, y + 2), imgui.ImVec2(x + fillW, y + 2 + barH), fillCol, rounding)\n    end\n    \n    local knobW = 8\n    local knobX = math.max(x, math.min(x + w - knobW, x + fillW - knobW))\n    drawList:AddRectFilled(imgui.ImVec2(knobX, y + 1), imgui.ImVec2(knobX + knobW, y + barH + 3), imgui.ImColor(255, 255, 255, 255):GetU32(), 3.0)\n    drawList:AddRect(imgui.ImVec2(knobX, y + 1), imgui.ImVec2(knobX + knobW, y + barH + 3), imgui.ImColor(200, 220, 255, 255):GetU32(), 3.0)\n    \n    imgui.Spacing()\n    return changed\nend\n\n-------------------------------------------------------------------------\n-- RENDERIZAÇÃO DA TELA IMGUI (OVERLAY VISUAL PROTEGIDO)\n-------------------------------------------------------------------------\nif okImgui then\n    function imgui.OnDrawFrame()\n        local sw, sh = getScreenResolution()\n\n        -- 1. OVERLAY DE ESP E FOV: Renderiza somente se o jogador estiver spawnado e fora de diálogos/login\n        if isPlayerReady() and ENABLE_VISUALS_RUNTIME then\n            imgui.SetNextWindowPos(imgui.ImVec2(0, 0), imgui.Cond.Always)\n            imgui.SetNextWindowSize(imgui.ImVec2(sw, sh), imgui.Cond.Always)\n            local overlayFlags = imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoMove + imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoScrollWithMouse + imgui.WindowFlags.NoInputs + imgui.WindowFlags.NoSavedSettings\n            \n            imgui.PushStyleColor(imgui.Col.WindowBg, imgui.ImVec4(0, 0, 0, 0))\n            imgui.PushStyleVar(imgui.StyleVar.WindowPadding, imgui.ImVec2(0, 0))\n            \n            if imgui.Begin("##SOMALIA_FULLSCREEN_OVERLAY", nil, overlayFlags) then\n                local drawList = imgui.GetWindowDrawList()\n                if drawList then\n                    if okVisuals and Visuals.render then pcall(Visuals.render, Config.data, drawList) end\n                    if okAim and Aim.renderFovCircle then pcall(Aim.renderFovCircle, Config.data, drawList) end\n                    if okHUD and HUD.render then pcall(HUD.render, Config.data, drawList) end\n                    if okNotifications and Notifications.render then pcall(Notifications.render, drawList) end\n                end\n                imgui.End()\n            end\n            imgui.PopStyleVar(1)\n            imgui.PopStyleColor(1)\n        end\n\n        -- 2. JANELA PRINCIPAL DO MENU (Só renderiza se janelaAberta.v for true)\n        if janelaAberta.v then\n            imgui.SetNextWindowPos(imgui.ImVec2(sw / 2, sh / 2), imgui.Cond.FirstUseEver, imgui.ImVec2(0.5, 0.5))\n            imgui.SetNextWindowSize(Theme.Sizes.Window, imgui.Cond.FirstUseEver)\n\n            local flags = imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoTitleBar\n            imgui.Begin("##SOMALIA_MAIN_FRAME", janelaAberta, flags)\n            \n            local azulNeon = Theme.Colors.AccentPrimary\n            local branco = Theme.Colors.TextPrimary\n            local winPos = imgui.GetWindowPos()\n            local winWidth = imgui.GetWindowWidth()\n\n            -- Transição de aba\n            if abaLateral ~= lastAbaLateral then\n                tabAlpha = 0.0\n                lastAbaLateral = abaLateral\n            end\n            tabAlpha = math.min(1.0, tabAlpha + 0.12)\n\n            -------------------------------------------------------------\n            -- TOP HEADER BAR (Logo SML + Perfil no canto direito)\n            -------------------------------------------------------------\n            imgui.SetCursorPosX(16)\n            imgui.SetCursorPosY(10)\n            \n            if Theme.Fonts.Logo then imgui.PushFont(Theme.Fonts.Logo) end\n            imgui.TextColored(branco, "SM")\n            imgui.SameLine(0, 0)\n            imgui.TextColored(azulNeon, "L")\n            if Theme.Fonts.Logo then imgui.PopFont() end\n            \n            DrawHeaderProfile(winPos.x + winWidth - 14, winPos.y + 8, "sx", "Owner")\n            \n            imgui.SetCursorPosY(44)\n            imgui.Spacing()\n\n            -------------------------------------------------------------\n            -- 1. SIDEBAR ESQUERDA (7 Abas Vetoriais 1:1)\n            -------------------------------------------------------------\n            imgui.BeginChild("##SidebarLeft", imgui.ImVec2(Theme.Sizes.SidebarWidth, 0), false, imgui.WindowFlags.NoScrollbar)\n                if DrawSidebarItem("side_aimbot", "Aimbot", "aimbot", (abaLateral == 1)) then abaLateral = 1 end\n                if DrawSidebarItem("side_visuals", "Visuals", "visuals", (abaLateral == 2)) then abaLateral = 2 end\n                if DrawSidebarItem("side_world", "World", "world", (abaLateral == 3)) then abaLateral = 3 end\n                if DrawSidebarItem("side_vehicles", "Vehicles", "vehicles", (abaLateral == 4)) then abaLateral = 4 end\n                if DrawSidebarItem("side_players", "Players", "players", (abaLateral == 5)) then abaLateral = 5 end\n                if DrawSidebarItem("side_exploits", "Exploits", "exploits", (abaLateral == 6)) then abaLateral = 6 end\n                if DrawSidebarItem("side_configs", "Configs", "configs", (abaLateral == 7)) then abaLateral = 7 end\n            imgui.EndChild()\n\n            imgui.SameLine(0, 10)\n\n            -------------------------------------------------------------\n            -- 2. ÁREA DE CONTEÚDO PRINCIPAL (COM CARDS LADO A LADO)\n            -------------------------------------------------------------\n            imgui.BeginChild("##MainContentArea", imgui.ImVec2(0, 0), false, imgui.WindowFlags.NoScrollbar)\n                imgui.PushStyleVar(imgui.StyleVar.Alpha, tabAlpha)\n                local larguraColuna = (imgui.GetWindowWidth() - 12) / 2\n\n                ---------------------------------------------------------\n                -- ABA 1: AIMBOT (SELETOR DE ARMA PRIMEIRO + SMOOTH TOTAL)\n                ---------------------------------------------------------\n                if abaLateral == 1 then\n                    -- CARD 1: AIMBOT (LEGIT)\n                    imgui.BeginChild("##CardAimbot", imgui.ImVec2(larguraColuna, 0), true)\n                        imgui.SetCursorPosX(12); imgui.SetCursorPosY(10)\n                        if Theme.Fonts.Title then imgui.PushFont(Theme.Fonts.Title) end\n                        imgui.TextColored(branco, "Aimbot")\n                        if Theme.Fonts.Title then imgui.PopFont() end\n                        imgui.Spacing()\n\n                        -- 1. SELETOR DE ARMA (PRIMEIRO COMPONENTE)\n                        DrawVideoCombo("Arma", weaponNames, Config.data.aim.selectedWeaponIndex or 0, "combo_aim_weapon", function(idx)\n                            Config.data.aim.selectedWeaponIndex = idx\n                        end)\n\n                        local curWIdx = (Config.data.aim.selectedWeaponIndex or 0) + 1\n                        local curWId = weaponIds[curWIdx] or 24\n                        local wAim = Config.getAimWeapon(curWId)\n\n                        -- 2. MASTER SWITCH & ATIVADO PARA ESTA ARMA\n                        DrawCheckboxWithKeybind("Aimbot Master", Config.data.aim.globalEnabled, Config.data.aim.key, "chk_aim_master", function(v)\n                            Config.data.aim.globalEnabled = v\n                            if okNotifications then Notifications.info("AIMBOT", v and "Aimbot Master Ativado" or "Aimbot Master Desativado") end\n                        end, function(id, k) Config.data.aim.key = k end)\n\n                        DrawVideoCheckbox("Ativado para esta Arma", wAim.enabled, "chk_w_aim_en_" .. curWId, function(v) wAim.enabled = v end)\n                        \n                        -- 3. FOV & SMOOTH\n                        DrawVideoSlider("FOV Size", wAim.fovSize, 5, 360, "px", "sld_w_aim_fov_" .. curWId, function(v) wAim.fovSize = v end)\n                        DrawVideoSlider("Smooth Horizontal", wAim.smoothH, 1, 50, "", "sld_w_aim_smooth_h_" .. curWId, function(v) wAim.smoothH = v end)\n                        DrawVideoSlider("Smooth Vertical", wAim.smoothV, 1, 50, "", "sld_w_aim_smooth_v_" .. curWId, function(v) wAim.smoothV = v end)\n\n                        -- 4. HITBOX & CHECKS\n                        DrawVideoCombo("Alvo (Hitbox)", hitboxOptions, wAim.hitbox, "combo_w_aim_hitbox_" .. curWId, function(idx) wAim.hitbox = idx end)\n                        DrawVideoCheckbox("Show FOV Circle", wAim.showFov, "chk_w_aim_showfov_" .. curWId, function(v) wAim.showFov = v end)\n                        DrawVideoCheckbox("Visible Check (Raycast)", wAim.visibleCheck, "chk_w_aim_vischeck_" .. curWId, function(v) wAim.visibleCheck = v end)\n                        DrawVideoCheckbox("Allow NPC", wAim.allowNpc, "chk_w_aim_allownpc_" .. curWId, function(v) wAim.allowNpc = v end)\n                        DrawVideoSlider("Max Distance", wAim.maxDist, 10, 300, "m", "sld_w_aim_maxdist_" .. curWId, function(v) wAim.maxDist = v end)\n                    imgui.EndChild()\n\n                    imgui.SameLine(0, 10)\n\n                    -- CARD 2: SILENT AIM (SELETOR DE ARMA PRIMEIRO)\n                    imgui.BeginChild("##CardSilent", imgui.ImVec2(larguraColuna, 0), true)\n                        imgui.SetCursorPosX(12); imgui.SetCursorPosY(10)\n                        if Theme.Fonts.Title then imgui.PushFont(Theme.Fonts.Title) end\n                        imgui.TextColored(branco, "Silent")\n                        if Theme.Fonts.Title then imgui.PopFont() end\n                        imgui.Spacing()\n\n                        -- 1. SELETOR DE ARMA (PRIMEIRO COMPONENTE)\n                        DrawVideoCombo("Arma", weaponNames, Config.data.silent.selectedWeaponIndex or 0, "combo_sil_weapon", function(idx)\n                            Config.data.silent.selectedWeaponIndex = idx\n                        end)\n\n                        local curSilWIdx = (Config.data.silent.selectedWeaponIndex or 0) + 1\n                        local curSilWId = weaponIds[curSilWIdx] or 24\n                        local wSil = Config.getSilentWeapon(curSilWId)\n\n                        -- 2. MASTER SWITCH & ATIVADO PARA ESTA ARMA\n                        DrawCheckboxWithKeybind("Silent Master", Config.data.silent.globalEnabled, Config.data.silent.key, "chk_sil_master", function(v)\n                            Config.data.silent.globalEnabled = v\n                            if okNotifications then Notifications.info("SILENT AIM", v and "Silent Master Ativado" or "Silent Master Desativado") end\n                        end, function(id, k) Config.data.silent.key = k end)\n\n                        DrawVideoCheckbox("Ativado para esta Arma", wSil.enabled, "chk_w_sil_en_" .. curSilWId, function(v) wSil.enabled = v end)\n                        DrawVideoSlider("FOV Size", wSil.fovSize, 5, 360, "px", "sld_w_sil_fov_" .. curSilWId, function(v) wSil.fovSize = v end)\n                        DrawVideoCombo("Alvo (Hitbox)", hitboxOptions, wSil.hitbox, "combo_w_sil_hitbox_" .. curSilWId, function(idx) wSil.hitbox = idx end)\n                        DrawVideoCheckbox("Show FOV Circle", wSil.showFov, "chk_w_sil_showfov_" .. curSilWId, function(v) wSil.showFov = v end)\n                        DrawVideoCheckbox("Visible Check (Raycast)", wSil.visibleCheck, "chk_w_sil_vischeck_" .. curSilWId, function(v) wSil.visibleCheck = v end)\n                        DrawVideoCheckbox("Allow NPC", wSil.allowNpc, "chk_w_sil_allownpc_" .. curSilWId, function(v) wSil.allowNpc = v end)\n                    imgui.EndChild()\n\n                ---------------------------------------------------------\n                -- ABA 2: VISUALS (Player ESP + Overlays)\n                ---------------------------------------------------------\n                elseif abaLateral == 2 then\n                    imgui.BeginChild("##CardVis1", imgui.ImVec2(larguraColuna, 0), true)\n                        imgui.SetCursorPosX(12); imgui.SetCursorPosY(10)\n                        if Theme.Fonts.Title then imgui.PushFont(Theme.Fonts.Title) end\n                        imgui.TextColored(branco, "Player ESP")\n                        if Theme.Fonts.Title then imgui.PopFont() end\n                        imgui.Spacing()\n\n                        DrawVideoCheckbox("Master ESP", Config.data.visuals.enabled, "vis_master", function(v)\n                            Config.data.visuals.enabled = v\n                            if okNotifications then Notifications.info("VISUALS", v and "ESP Ativado" or "ESP Desativado") end\n                        end)\n                        DrawVideoCheckbox("2D Box ESP", Config.data.visuals.boxEsp, "vis_box", function(v) Config.data.visuals.boxEsp = v end)\n                        DrawVideoCheckbox("Corner Box", Config.data.visuals.cornerBox, "vis_corner", function(v) Config.data.visuals.cornerBox = v end)\n                        DrawVideoCheckbox("Skeleton ESP", Config.data.visuals.skeleton, "vis_skel", function(v) Config.data.visuals.skeleton = v end)\n                        DrawVideoCheckbox("Health Bar", Config.data.visuals.healthBar, "vis_hp", function(v) Config.data.visuals.healthBar = v end)\n                        DrawVideoCheckbox("Armor Bar", Config.data.visuals.armorBar, "vis_arm", function(v) Config.data.visuals.armorBar = v end)\n                        DrawVideoCheckbox("Player Names", Config.data.visuals.playerNames, "vis_name", function(v) Config.data.visuals.playerNames = v end)\n                        DrawVideoCheckbox("Player ID", Config.data.visuals.playerId, "vis_id", function(v) Config.data.visuals.playerId = v end)\n                    imgui.EndChild()\n\n                    imgui.SameLine(0, 10)\n\n                    imgui.BeginChild("##CardVis2", imgui.ImVec2(larguraColuna, 0), true)\n                        imgui.SetCursorPosX(12); imgui.SetCursorPosY(10)\n                        if Theme.Fonts.Title then imgui.PushFont(Theme.Fonts.Title) end\n                        imgui.TextColored(branco, "World ESP & Overlays")\n                        if Theme.Fonts.Title then imgui.PopFont() end\n                        imgui.Spacing()\n\n                        DrawVideoCheckbox("Snaplines", Config.data.visuals.snaplines, "vis_snap", function(v) Config.data.visuals.snaplines = v end)\n                        DrawVideoCheckbox("Distance ESP", Config.data.visuals.distance, "vis_dist", function(v) Config.data.visuals.distance = v end)\n                        DrawVideoSlider("Max ESP Distance", Config.data.visuals.maxDistance, 50, 400, "m", "sld_vis_dist", function(v) Config.data.visuals.maxDistance = v end)\n                    imgui.EndChild()\n\n                ---------------------------------------------------------\n                -- ABA 3: WORLD (Clima e Horário)\n                ---------------------------------------------------------\n                elseif abaLateral == 3 then\n                    imgui.BeginChild("##CardWorld", imgui.ImVec2(larguraColuna, 0), true)\n                        imgui.SetCursorPosX(12); imgui.SetCursorPosY(10)\n                        if Theme.Fonts.Title then imgui.PushFont(Theme.Fonts.Title) end\n                        imgui.TextColored(branco, "World Controller")\n                        if Theme.Fonts.Title then imgui.PopFont() end\n                        imgui.Spacing()\n\n                        DrawVideoCheckbox("Custom Time Enabled", Config.data.world.customTimeEnabled, "w_time_en", function(v) Config.data.world.customTimeEnabled = v end)\n                        DrawVideoSlider("Hour (0h - 23h)", Config.data.world.customHour, 0, 23, "h", "w_hour", function(v) Config.data.world.customHour = v end)\n                        \n                        imgui.Spacing(); imgui.Separator(); imgui.Spacing()\n                        \n                        DrawVideoCheckbox("Custom Weather Enabled", Config.data.world.customWeatherEnabled, "w_weath_en", function(v) Config.data.world.customWeatherEnabled = v end)\n                        DrawVideoSlider("Weather ID", Config.data.world.weatherId, 0, 45, "", "w_wid", function(v) Config.data.world.weatherId = v end)\n                    imgui.EndChild()\n\n                ---------------------------------------------------------\n                -- ABA 4: VEHICLES\n                ---------------------------------------------------------\n                elseif abaLateral == 4 then\n                    imgui.BeginChild("##CardVeh", imgui.ImVec2(larguraColuna, 0), true)\n                        imgui.SetCursorPosX(12); imgui.SetCursorPosY(10)\n                        if Theme.Fonts.Title then imgui.PushFont(Theme.Fonts.Title) end\n                        imgui.TextColored(branco, "Vehicle Enhancements")\n                        if Theme.Fonts.Title then imgui.PopFont() end\n                        imgui.Spacing()\n\n                        DrawCheckboxWithKeybind("Speed Boost", Config.data.vehicles.speedBoost, Config.data.vehicles.speedBoostKey, "chk_v_boost", function(v)\n                            Config.data.vehicles.speedBoost = v\n                        end, function(id, k) Config.data.vehicles.speedBoostKey = k end)\n                        \n                        DrawCheckboxWithKeybind("Instant Repair (R)", Config.data.vehicles.instantRepair, Config.data.vehicles.instantRepairKey, "chk_v_rep", function(v)\n                            Config.data.vehicles.instantRepair = v\n                        end, function(id, k) Config.data.vehicles.instantRepairKey = k end)\n\n                        DrawCheckboxWithKeybind("Flip Car (X)", Config.data.vehicles.flipCar, Config.data.vehicles.flipCarKey, "chk_v_flip", function(v)\n                            Config.data.vehicles.flipCar = v\n                        end, function(id, k) Config.data.vehicles.flipCarKey = k end)\n\n                        DrawVideoCheckbox("Vehicle Godmode", Config.data.vehicles.godmode, "chk_v_god", function(v) Config.data.vehicles.godmode = v end)\n                        DrawVideoCheckbox("Engine Always On", Config.data.vehicles.engineAlwaysOn, "chk_v_eng", function(v) Config.data.vehicles.engineAlwaysOn = v end)\n                    imgui.EndChild()\n\n                ---------------------------------------------------------\n                -- ABA 5: PLAYERS (C-SLIDE & MOVIMENTO)\n                ---------------------------------------------------------\n                elseif abaLateral == 5 then\n                    -- CARD 1: C-Slide & Mecânicas\n                    imgui.BeginChild("##CardSlide1", imgui.ImVec2(larguraColuna, 0), true)\n                        imgui.SetCursorPosX(12); imgui.SetCursorPosY(10)\n                        if Theme.Fonts.Title then imgui.PushFont(Theme.Fonts.Title) end\n                        imgui.TextColored(branco, "C-Slide & Movement")\n                        if Theme.Fonts.Title then imgui.PopFont() end\n                        imgui.Spacing()\n\n                        DrawVideoCheckbox("Script Geral (Master)", Config.data.player.scriptAtivo, "chk_slide_master", function(v) Config.data.player.scriptAtivo = v end)\n                        DrawVideoCheckbox("C-Slide Ativo", Config.data.player.cSlideAtivo, "chk_slide_cslide", function(v) Config.data.player.cSlideAtivo = v end)\n                        DrawVideoCheckbox("Auto Slide (Quick Switch)", Config.data.player.autoSlideAtivo, "chk_slide_auto", function(v) Config.data.player.autoSlideAtivo = v end)\n\n                        DrawVideoSlider("Duração da Tecla C", Config.data.player.duracaoC, 5, 100, "ms", "sld_slide_durc", function(v) Config.data.player.duracaoC = v end)\n                        DrawVideoSlider("Delay pós-tiro", Config.data.player.delayTroca, 0, 250, "ms", "sld_slide_delay", function(v) Config.data.player.delayTroca = v end)\n                        \n                        imgui.Spacing(); imgui.Separator(); imgui.Spacing()\n                        DrawVideoCheckbox("Infinite Stamina", Config.data.player.infiniteStamina, "chk_p_infstam", function(v) Config.data.player.infiniteStamina = v end)\n                        DrawVideoCheckbox("No Fall Damage", Config.data.player.noFallDamage, "chk_p_nofall", function(v) Config.data.player.noFallDamage = v end)\n                    imgui.EndChild()\n\n                    imgui.SameLine(0, 10)\n\n                    -- CARD 2: Margens por Arma\n                    imgui.BeginChild("##CardSlide2", imgui.ImVec2(larguraColuna, 0), true)\n                        imgui.SetCursorPosX(12); imgui.SetCursorPosY(10)\n                        if Theme.Fonts.Title then imgui.PushFont(Theme.Fonts.Title) end\n                        imgui.TextColored(branco, "Weapon Margins")\n                        if Theme.Fonts.Title then imgui.PopFont() end\n                        imgui.Spacing()\n\n                        DrawVideoSlider("Desert Eagle (Deagle)", Config.data.player.margem_desert, 0, 1000, "ms", "sld_m_deagle", function(v) Config.data.player.margem_desert = v end)\n                        DrawVideoSlider("Shotgun", Config.data.player.margem_shot, 0, 1000, "ms", "sld_m_shot", function(v) Config.data.player.margem_shot = v end)\n                        DrawVideoSlider("Sniper Rifle", Config.data.player.margem_snp, 0, 1000, "ms", "sld_m_snp", function(v) Config.data.player.margem_snp = v end)\n                        DrawVideoSlider("M4 Assault", Config.data.player.margem_m4, 0, 1000, "ms", "sld_m_m4", function(v) Config.data.player.margem_m4 = v end)\n                        DrawVideoSlider("AK-47", Config.data.player.margem_ak, 0, 1000, "ms", "sld_m_ak", function(v) Config.data.player.margem_ak = v end)\n                    imgui.EndChild()\n\n                ---------------------------------------------------------\n                -- ABA 6: EXPLOITS & HUD\n                ---------------------------------------------------------\n                elseif abaLateral == 6 then\n                    imgui.BeginChild("##CardExpl", imgui.ImVec2(larguraColuna, 0), true)\n                        imgui.SetCursorPosX(12); imgui.SetCursorPosY(10)\n                        if Theme.Fonts.Title then imgui.PushFont(Theme.Fonts.Title) end\n                        imgui.TextColored(branco, "Exploits")\n                        if Theme.Fonts.Title then imgui.PopFont() end\n                        imgui.Spacing()\n\n                        DrawVideoCheckbox("No Recoil", Config.data.misc.noRecoil, "e_norec", function(v) Config.data.misc.noRecoil = v end)\n                        DrawVideoCheckbox("No Spread", Config.data.misc.noSpread, "e_nospread", function(v) Config.data.misc.noSpread = v end)\n                        DrawVideoCheckbox("Fast Reload", Config.data.misc.fastReload, "e_fastrel", function(v) Config.data.misc.fastReload = v end)\n                    imgui.EndChild()\n\n                    imgui.SameLine(0, 10)\n\n                    imgui.BeginChild("##CardHUD", imgui.ImVec2(larguraColuna, 0), true)\n                        imgui.SetCursorPosX(12); imgui.SetCursorPosY(10)\n                        if Theme.Fonts.Title then imgui.PushFont(Theme.Fonts.Title) end\n                        imgui.TextColored(branco, "HUD & Watermark")\n                        if Theme.Fonts.Title then imgui.PopFont() end\n                        imgui.Spacing()\n\n                        DrawVideoCheckbox("Watermark Superior", Config.data.hud.watermark, "hud_wm", function(v) Config.data.hud.watermark = v end)\n                        DrawVideoCheckbox("Coordenadas X/Y/Z", Config.data.hud.coords, "hud_coords", function(v) Config.data.hud.coords = v end)\n                        DrawVideoCheckbox("Active Features List", Config.data.hud.activeFeatures, "hud_active", function(v) Config.data.hud.activeFeatures = v end)\n                    imgui.EndChild()\n\n                ---------------------------------------------------------\n                -- ABA 7: CONFIGS & PERFIS\n                ---------------------------------------------------------\n                elseif abaLateral == 7 then\n                    imgui.BeginChild("##CardCfg", imgui.ImVec2(larguraColuna, 0), true)\n                        imgui.SetCursorPosX(12); imgui.SetCursorPosY(10)\n                        if Theme.Fonts.Title then imgui.PushFont(Theme.Fonts.Title) end\n                        imgui.TextColored(branco, "Config Profiles")\n                        if Theme.Fonts.Title then imgui.PopFont() end\n                        imgui.Spacing()\n\n                        imgui.TextColored(Theme.Colors.TextSecondary, u8"Perfil Ativo: " .. string.upper(Config.currentProfile))\n                        imgui.Spacing()\n\n                        for idx, pName in ipairs(Config.profilesList) do\n                            local isSelected = (Config.currentProfile == pName)\n                            if imgui.Button((isSelected and "> " or "  ") .. string.upper(pName) .. "##prof_" .. idx, imgui.ImVec2(-1, 28)) then\n                                Config.load(pName)\n                                if okNotifications then Notifications.success("CONFIG", "Perfil " .. string.upper(pName) .. " Carregado") end\n                            end\n                        end\n                        \n                        imgui.Spacing()\n                        if imgui.Button("Salvar Configuracoes##btn_save", imgui.ImVec2(-1, 30)) then\n                            Config.save()\n                            if okNotifications then Notifications.success("CONFIG", "Configuracoes Salvas!") end\n                        end\n\n                        if imgui.Button("Resetar Padrao##btn_reset", imgui.ImVec2(-1, 30)) then\n                            Config.reset()\n                            if okNotifications then Notifications.warning("CONFIG", "Configuracao Resetada") end\n                        end\n                    imgui.EndChild()\n\n                    imgui.SameLine(0, 10)\n\n                    imgui.BeginChild("##CardCfg2", imgui.ImVec2(larguraColuna, 0), true)\n                        imgui.SetCursorPosX(12); imgui.SetCursorPosY(10)\n                        if Theme.Fonts.Title then imgui.PushFont(Theme.Fonts.Title) end\n                        imgui.TextColored(branco, "System & Keys")\n                        if Theme.Fonts.Title then imgui.PopFont() end\n                        imgui.Spacing()\n\n                        imgui.TextColored(Theme.Colors.TextSecondary, u8"Menu Keybind:")\n                        if okKeybinds then\n                            Keybinds.drawKeybindButton("menu_key", Config.data.system.menuKey, function(id, k) Config.data.system.menuKey = k end, 120)\n                        end\n                        \n                        imgui.Spacing(); imgui.Separator(); imgui.Spacing()\n                        imgui.TextColored(Theme.Colors.TextSecondary, u8"Comandos de Chat:")\n                        imgui.TextColored(branco, "/sml  |  /somalia  |  /slide  |  /menu")\n                        imgui.Spacing()\n                        imgui.TextColored(Theme.Colors.TextMuted, "Somalia Client Edition v1.3.0")\n                    imgui.EndChild()\n                end\n\n                imgui.PopStyleVar(1)\n            imgui.EndChild()\n\n            imgui.End()\n        end\n    end\nend\n\n-------------------------------------------------------------------------\n-- MAIN THREAD DO MOONLOADER - BOOT SEGURO E GATING VISUAL\n-------------------------------------------------------------------------\nfunction main()\n    print("[SOMALIA][BOOT] 01 - main iniciado")\n    \n    local isSamp = isSampLoaded()\n    print("[SOMALIA][BOOT] 02 - status SA-MP carregado: " .. tostring(isSamp))\n    print("[SOMALIA][BOOT] 03 - status ImGui carregado: " .. tostring(okImgui))\n    print("[SOMALIA][BOOT] 04 - config e temas carregados")\n\n    -- Aguarda o SA-MP ficar completamente pronto\n    while not isSampAvailable() do \n        wait(100) \n    end\n    print("[SOMALIA][BOOT] 05 - SA-MP esta pronto e disponivel!")\n    print("[SOMALIA][BOOT] 06 - MODO VISUAL (ESP + FOV AIMBOT + FOV SILENT ATIVOS)")\n\n    local function toggleMenu()\n        if okImgui then\n            janelaAberta.v = not janelaAberta.v\n            sampAddChatMessage("{0080FF}[SOMALIA]{FFFFFF} Menu alternado para: " .. tostring(janelaAberta.v), -1)\n        else\n            sampAddChatMessage("{FF0000}[SOMALIA ERRO]{FFFFFF} Biblioteca \'imgui\' nao encontrada em moonloader/lib!", -1)\n        end\n    end\n\n    local function commandHandler()\n        sampAddChatMessage("{0080FF}[SOMALIA]{FFFFFF} COMANDO DETECTADO!", -1)\n        toggleMenu()\n    end\n\n    sampRegisterChatCommand("sml", commandHandler)\n    sampRegisterChatCommand("somalia", commandHandler)\n    sampRegisterChatCommand("slide", commandHandler)\n    sampRegisterChatCommand("menu", commandHandler)\n\n    if okTheme and Theme.applyStyle then Theme.applyStyle() end\n\n    if okImgui then\n        sampAddChatMessage("{0080FF}[SOMALIA]{FFFFFF} Somalia Carregado! Pressione {0080FF}F5{FFFFFF} ou digite {0080FF}/sml{FFFFFF}.", -1)\n        if okNotifications then Notifications.success("SOMALIA", "Carregado com sucesso! [F5]") end\n        print("[SOMALIA][BOOT] 07 - Somalia inicializado com sucesso! Atalho F5 pronto.")\n    end\n\n    print("[SOMALIA][BOOT] 08 - entrando no loop principal")\n\n    while true do\n        wait(0)\n\n        -- Escuta de tecla para redefinição de keybinds interativos (apenas se fora de diálogos/chat)\n        if okKeybinds and Keybinds.processListening then\n            Keybinds.processListening(function(id, newKey)\n                if id == "menu_key" then\n                    Config.data.system.menuKey = newKey\n                elseif id == "chk_aim_master" then\n                    Config.data.aim.key = newKey\n                elseif id == "chk_sil_master" then\n                    Config.data.silent.key = newKey\n                elseif id == "chk_v_boost" then\n                    Config.data.vehicles.speedBoostKey = newKey\n                elseif id == "chk_v_rep" then\n                    Config.data.vehicles.instantRepairKey = newKey\n                elseif id == "chk_v_flip" then\n                    Config.data.vehicles.flipCarKey = newKey\n                end\n                if okConfig and Config.save then Config.save() end\n                if okNotifications then Notifications.info("KEYBIND", "Atalho atualizado: " .. Keybinds.getKeyName(newKey)) end\n            end)\n        end\n\n        -- Abertura e fechamento do Menu via Keybind configurável ou F5 direto (ignora durante diálogos/chat)\n        local menuKey = (okConfig and Config.data.system.menuKey) or 0x74 -- F5\n        if isKeyJustPressed(menuKey) or isKeyJustPressed(0x74) then\n            toggleMenu()\n        end\n\n        local inGame = isPlayerReady()\n        local visualsActive = inGame and Config.data.visuals and Config.data.visuals.enabled or false\n        local curW = okAim and Aim.getCurrentWeaponId and Aim.getCurrentWeaponId() or 0\n        \n        -- Checagem de FOV Aimbot e Silent Aim ativos para a arma atual\n        local wAim = okConfig and Config.getAimWeapon and Config.getAimWeapon(curW) or nil\n        local wSil = okConfig and Config.getSilentWeapon and Config.getSilentWeapon(curW) or nil\n        local fovAimActive = inGame and (curW > 0) and (Config.data.aim and Config.data.aim.globalEnabled and wAim and wAim.enabled and wAim.showFov) or false\n        local fovSilActive = inGame and (curW > 0) and (Config.data.silent and Config.data.silent.globalEnabled and wSil and wSil.enabled and wSil.showFov) or false\n        local fovAnyActive = fovAimActive or fovSilActive\n\n        -- CONTROLE SEGURO DE IMGUI: Processa frames somente se menu aberto OU jogador spawnado com ESP/FOV\n        if okImgui then\n            imgui.Process = janelaAberta.v or (inGame and (visualsActive or fovAnyActive))\n            imgui.ShowCursor = janelaAberta.v\n            imgui.DisableInput = not janelaAberta.v\n        end\n\n        -- PROCESSAMENTO DE GAMEPLAY (PERMANECE DESATIVADO NESTA ETAPA)\n        if ENABLE_GAMEPLAY_RUNTIME and inGame then\n            if okPlayer and Player.process then pcall(Player.process, Config.data) end\n            if okAim and Aim.process then pcall(Aim.process, Config.data) end\n            if okVehicles and Vehicles.process then pcall(Vehicles.process, Config.data) end\n            if okWorld and World.process then pcall(World.process, Config.data) end\n            if okMisc and Misc.process then pcall(Misc.process, Config.data) end\n        end\n\n        -- DIAGNÓSTICO THROTTLED A CADA 2.0 SEGUNDOS\n        lastDebugTick = lastDebugTick or 0\n        local nowClock = os.clock()\n        if (nowClock - lastDebugTick) >= 2.0 then\n            lastDebugTick = nowClock\n            print(string.format(\n                "[SOMALIA][STATUS] InGame: %s | Menu: %s | ESP: %s | FOV Aim: %s | FOV Silent: %s (Arma %d)",\n                tostring(inGame),\n                tostring(janelaAberta.v),\n                tostring(visualsActive),\n                tostring(fovAimActive),\n                tostring(fovSilActive),\n                curW\n            ))\n        end\n    end\nend'}
